q=A.Z(new A.aM(A.b([A.a2(["title","Th\u1eddi \u0110\u1ea1i \u201cV\xf4 C\xf9ng Nguy Ng\u1eadp\u201d","meta",s,"preview","H\u01a1n ph\xe2n n\u1eeda nh\xe2n lo\u1ea1i s\u1ebd b\u1ecb h\u1ee7y di\u1ec7t, v\xe0 nh\u1eefng ng\u01b0\u1eddi s\u1ed1ng s\xf3t l\xe0 nh\u1eefng ng\u01b0\u1eddi bi\u1ebft tu \u0110\u1ea1o, nh\u1eefng ng\u01b0\u1eddi ch\xe2n th\u1eadt tu h\xe0nh, nh\u1eefng ng\u01b0\u1eddi bi\u1ebft ni\u1ec7m Ph\u1eadt, nh\u1eefng ng\u01b0\u1eddi bi\u1ebft t\u1ee5ng Kinh v\xe0 nh\u1eefng ng\u01b0\u1eddi \u0103n chay, \u0111\xf3 l\xe0 nh\u1eefng ng\u01b0\u1eddi c\xf3 th\u1ec3 s\u1ed1ng c\xf2n.\n\nKh\xf4ng ph\u1ea3i t\xf4i c\u1ed1 \xfd n\xf3i nh\u1eefng l\u1eddi n\xe0y \u0111\u1ec3 h\xf9 d\u1ecda qu\xfd v\u1ecb. \u0110\xe3 \u0111\u1ebfn l\xfac t\xf4i kh\xf4ng th\u1ec3 kh\xf4ng l\xean ti\u1ebfng, th\u1eddi \u0111\u1ea1i n\xe0y kh\xf4ng ph\u1ea3i l\xe0 th\u1eddi \u0111\u1ea1i h\xf2a b\xecnh, \u0111\xe2y l\xe0 m\u1ed9t th\u1eddi \u0111\u1ea1i \u201cV\xf4 C\xf9ng Nguy Ng\u1eadp\u201d"],q,q),A.a2(["title","PH\xc1P KI\u1ebeT T\u01af\u1edcNG (Trong Th\u1ea7n Ch\xfa L\u0103ng Nghi\xeam)","meta",s,"preview","Ph\xe1p Ki\u1ebft T\u01b0\u1eddng: T\u1ee5ng tr\xec th\u1ea7n ch\xfa n\xe0y th\xec t\u1ea5t c\u1ea3 s\u1ef1 vi\u1ec7c \u0111\u1ec1u t\xf9y t\xe2m nh\u01b0 \xfd, th\u1eadt ki\u1ebft t\u01b0\u1eddng may m\u1eafn. T\xf4i s\u1ebd gi\u1ea3i th\xedch r\xf5 nh\u1eefng ph\xe1p n\xe0y cho qu\xfd v\u1ecb.\n\nD\u1eabu c\xf3 gi\u1ea3ng nhi\u1ec1u n\u0103m m\xe0 v\u1eabn kh\xf4ng th\u1ec3 gi\u1ea3ng h\u1ebft nh\u1eefng \u0111i\u1ec3m hay c\u1ee7a th\u1ea7n ch\xfa n\xe0y. T\u1ea5t c\u1ea3 10 ph\u01b0\u01a1ng ch\u01b0 Ph\u1eadt \u0111\u1ec1u sanh xu\u1ea5t t\u1eeb th\u1ea7n ch\xfa n\xe0y, n\xean c\xf3 th\u1ec3 g\u1ecdi l\xe0 th\u1ea7n ch\xfa L\u0103ng Nghi\xeam l\xe0 m\u1eb9 c\u1ee7a ch\u01b0 Ph\u1eadt."],q,q),A.a2(["title","C\u1ed9t M\u1ed1c 36.000 Bi\u1ebfn & \u0110\xe0i Sen N\xe2ng \u0110\u1ee1","meta",r,"preview","Khi m\u1ed9t h\xe0nh gi\u1ea3 ch\xed t\xe2m tr\xec t\u1ee5ng \u0111\u1ea1t t\u1edbi c\u1ed9t m\u1ed1c t\u1ed1i th\u01b0\u1ee3ng 36.000 bi\u1ebfn, nh\u1eefng ph\xe9p m\u1ea7u hi\u1ec7n ti\u1ec1n s\u1ebd h\xf3a sinh. T\xedch l\u0169y \u0111\u1ee7 36.000 l\u1ea7n m\u1ed9t c\xe1ch chu\u1ea9n x\xe1c, m\u1ed9t hi\u1ec7n t\u01b0\u1ee3ng vi di\u1ec7u s\u1ebd xu\u1ea5t hi\u1ec7n: d\u01b0\u1edbi th\xe2n ng\u01b0\u1eddi \u0111\xf3 s\u1ebd hi\u1ec7n ra m\u1ed9t \u0111\xe0i sen n\xe2ng \u0111\u1ee1 trong kho\u1ea3ng kh\xf4ng v\xf4 h\xecnh."],q,q),A.a2(["title","\u0110\u1ecbnh Qu\u1ed1c V\xe3ng Sinh \u2014 36.000 \u0110\u1ea1o H\xe0o Quang","meta",r,"preview","M\u1ed7i bi\u1ebfn Ch\xfa L\u0103ng Nghi\xeam \u0111\u01b0\u1ee3c t\u1ee5ng l\xean gi\u1ed1ng nh\u01b0 vi\u1ec7c v\u1ebd m\u1ed9t \u0111\u1ea1o h\xe0o quang r\u1ef1c r\u1ee1 bao b\u1ecdc xung quanh c\u01a1 th\u1ec3. Do \u0111\xf3, khi t\u1ee5ng \u0111\u1ee7 36.000 bi\u1ebfn, th\xe2n t\xe2m h\xe0nh gi\u1ea3 s\u1ebd c\xf3 36.000 \u0111\u1ea1o h\xe0o quang ki\xean c\u1ed1 b\u1ea3o v\u1ec7, ch\u1eafc ch\u1eafn tho\xe1t kh\u1ecfi ba \u0111\u01b0\u1eddng \xe1c nghi\u1ec7p."],q,q),A.a2(["title","C\u1ee9u \u0110\u1ed9 Cha M\u1eb9 Trong B\u1ea3y \u0110\u1eddi Nhi\u1ec1u Ki\u1ebfp","meta",r,"preview","N\u0103ng l\u1ef1c c\u1ee7a 36.000 bi\u1ebfn t\u1ee5ng kh\xf4ng ch\u1ec9 \u0111em l\u1ea1i s\u1ef1 th\xe0nh t\u1ef1u ri\xeang cho b\u1ea3n th\xe2n, m\xe0 c\xf2n t\u1ecfa n\u0103ng l\u01b0\u1ee3ng c\u1ee9u \u0111\u1ed9 to l\u1edbn. C\xf4ng \u0111\u1ee9c th\xf9 th\u1eafng n\xe0y c\xf3 th\u1ec3 gi\xfap c\u1ee9u \u0111\u1ed9 cha m\u1eb9 trong b\u1ea3y \u0111\u1eddi, th\u1eadm ch\xed l\xe0 cha m\u1eb9 trong nhi\u1ec1u ki\u1ebfp qu\xe1 kh\u1ee9 \u0111\u1ec1u \u0111\u01b0\u1ee3c gi\u1ea3i tho\xe1t si\xeau sinh."],q,q),A.a2(["title","S\u1ef1 T\u1ed3n Vong C\u1ee7a Ch\xe1nh Ph\xe1p","meta",s,"preview","Ch\xfa L\u0103ng Nghi\xeam l\xe0 linh v\u0103n c\u1ee9u m\u1ea1ng c\u1ee7a tr\u1eddi \u0111\u1ea5t. B\u1ea5t c\u1ee9 l\xfac n\xe0o c\u0169ng ph\u1ea3i c\xf3 ng\u01b0\u1eddi tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam \u0111\u1ec3 ch\u1ed1ng \u0111\u1ee1 tr\u1eddi \u0111\u1ea5t, kh\xf4ng \u0111\u1ec3 cho th\u1ebf gi\u1edbi \u0111i \u0111\u1ebfn ch\u1ed7 ho\u1ea1i di\u1ec7t. N\u1ebfu kh\xf4ng c\xf2n ai t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam n\u1eefa, th\u1ebf gi\u1edbi n\xe0y s\u1ebd nhanh ch\xf3ng \u0111i \u0111\u1ebfn c\xf5i di\u1ec7t."],q,q),A.a2(["title","C\u1ea3nh Gi\u1edbi Th\xe2n Kim Cang B\u1ea5t Ho\u1ea1i","meta",r,"preview","Qu\xe1 tr\xecnh tinh t\u1ea5n tr\xec t\u1ee5ng \u0111\u1ea1i th\u1ea7n ch\xfa gi\xfap tr\u01b0\u1ee3c kh\xed gi\u1ea3m s\xe2u, thanh kh\xed th\u0103ng ti\u1ebfn, chuy\u1ec3n h\xf3a ph\xe0m th\xe2n th\xe0nh Th\xe2n Kim Cang. C\u01a1 th\u1ec3 tr\u1edf n\xean c\u1ee9ng ch\u1eafc nh\u01b0 \u0111\u1ed3ng s\u1eaft, h\xe0m r\u0103ng 36 chi\u1ebfc t\u1ef1 m\u1ecdc l\u1ea1i, v\xe0 th\xe2n th\u1ec3 t\u1ef1 t\u1ecfa m\xf9i h\u01b0\u01a1ng \u0111\xe0n h\u01b0\u01a1ng n\u1ed3ng n\xe0n b\u1ea5t bi\u1ebfn."],q,q),A.a2(["title","B\xe1ch \u0110\u1ed9c B\u1ea5t S\xe2m & Th\u1ea7n Th\xf4ng Mu\xf4ng Th\xfa","meta",r,"preview","Th\xe2n th\u1ec3 mi\u1ec5n nhi\u1ec5m ho\xe0n to\xe0n v\u1edbi t\u1ea5t c\u1ea3 b\u1ec7nh t\u1eadt, \u0111\u1ed9c ch\u1ea5t. \u0110\u1eb7c bi\u1ec7t, khi h\xe0nh gi\u1ea3 tr\xec t\u1ee5ng v\u01b0\u1ee3t qua m\u1ed1c 1.000.000 bi\u1ebfn, h\u1ecd s\u1ebd \u0111\u1eafc \u0111\u01b0\u1ee3c kh\u1ea3 n\u0103ng th\u1ea5u hi\u1ec3u ng\xf4n ng\u1eef c\u1ee7a mu\xf4n lo\xe0i \u0111\u1ed9ng v\u1eadt, tho\xe1t kh\u1ecfi th\u1ebf gi\u1edbi h\u01b0 \u1ea3o huy\u1ec5n c\u1ea3nh."],q,q),A.a2(["title","V\xec Sao Tr\xec L\u0103ng Nghi\xeam Ch\xfa Ph\u1ea3i Ni\u1ec7m L\u1edbn Ti\u1ebfng","meta",r,"preview","Ph\xe0m l\xe0 ng\u01b0\u1eddi \u0111\u1ebfn Quan \xc2m C\u1ed5 \u0110\u1ed9ng tu h\xe0nh th\xec nh\u1ea5t \u0111\u1ecbnh ph\u1ea3i ni\u1ec7m l\u1edbn ti\u1ebfng. V\xec sao th\u1ea7y k\xeau c\xe1c Ph\u1eadt t\u1eed ni\u1ec7m l\u1edbn ti\u1ebfng? Ni\u1ec7m l\u1edbn ti\u1ebfng L\u0103ng Nghi\xeam Ch\xfa, th\xec hoa sen c\u1ee7a c\xe1c Ph\u1eadt t\u1eed c\u0169ng l\u1edbn theo. Ni\u1ec7m cho t\u1ed1t th\xec cha m\u1eb9 \u0111\u1ec1u \u0111\u01b0\u1ee3c l\u1ee3i \xedch, \u0111\u1ec1u \u0111\u01b0\u1ee3c ng\u1ed3i tr\xean hoa sen. C\xe1c Ph\u1eadt t\u1eed xem Th\xedch Ca M\xe2u Ni Ph\u1eadt, D\u01b0\u1ee3c S\u01b0 Ph\u1eadt, A Di \u0110\xe0 Ph\u1eadt trong \u0110\u1ea1i H\xf9ng B\u1ea3o \u0110i\u1ec7n, c\xe1c Ng\xe0i \u0111\u1ec1u ng\u1ed3i tr\xean hoa sen 5 t\u1ea7ng.\n\nNi\u1ec7m l\u1edbn ti\u1ebfng L\u0103ng Nghi\xeam Ch\xfa kh\xf4ng ch\u1ec9 c\xf3 l\u1ee3i cho b\u1ea3n th\xe2n. N\xf3 c\xf2n c\xf3 th\u1ec3 \u0111\u1ea3 th\xf4ng to\xe0n b\u1ed9 kinh m\u1ea1ch trong th\xe2n th\u1ec3. Ni\u1ec7m l\u1edbn ti\u1ebfng th\xec s\u1ebd kh\xf4ng c\xf2n \u0111\u1ee7 th\u1ee9 v\u1ecdng t\u01b0\u1edfng n\u1eefa.\n\nV\xec sao c\u1ea3 \u0111\u1eddi th\u1ea7y kh\xf4ng cho ph\xe9p m\u1eb7c ni\u1ec7m v\xe0 ni\u1ec7m nh\u1ecf ti\u1ebfng? Ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa ph\u1ea3i h\xe9t to ra, \xe2m thanh c\xe0ng l\u1edbn c\xe0ng t\u1ed1t. Th\u1ea7y th\xedch nh\u1ea5t l\xe0 ng\u01b0\u1eddi c\xf3 \xe2m thanh l\u1edbn. Khi h\xe9t to ra r\u1ed3i, th\xec th\xe2n v\xe0 t\xe2m c\u1ee7a Ph\u1eadt t\u1eed \u0111\u1ec1u \u1edf trong c\xe2u ch\xfa, s\u1ebd kh\xf4ng \u0111i kh\u1edfi v\u1ecdng t\u01b0\u1edfng n\u1eefa. \u0110\u1ee7 th\u1ee9 b\u1ec7nh t\u1eadt c\u0169ng kh\xf4ng c\xf2n. C\u0169ng s\u1ebd kh\xf4ng c\xf3 50 lo\u1ea1i \u1ea5m ma. \u1ea4m ma l\xe0 g\xec? Ch\xednh l\xe0 t\xe0 t\u01b0 t\xe0 ki\u1ebfn trong t\xe2m c\u1ee7a ch\xednh m\xecnh, nh\u01b0 v\u1eady l\xe0 b\u1ecb ma \xe1m r\u1ed3i.\n\nNi\u1ec7m l\u1edbn ti\u1ebfng L\u0103ng Nghi\xeam Ch\xfa, h\u1ebft th\u1ea3y ma \u0111\u1ec1u kh\xf4ng c\xf2n. Ch\xfang n\xf3 t\u1eeb xa \u0111\u1ec1u qu\u1ef3 xu\u1ed1ng d\u1eadp \u0111\u1ea7u \u0111\u1ea3nh l\u1ec5 Ph\u1eadt t\u1eed. Cho \u0111\u1ebfn nh\u1eefng con tr\xf9ng con ki\u1ebfn, t\u1ea5t c\u1ea3 ch\xfang sinh, ch\u1ec9 c\u1ea7n nghe \u0111\u01b0\u1ee3c th\xf4i, v\u1ecb lai \u0111\u1ec1u s\u1ebd th\xe0nh Ph\u1eadt.\n\nM\u1ed7i m\u1ed9t ch\u1eef m\u1ed7i m\u1ed9t c\xe2u c\u1ee7a L\u0103ng Nghi\xeam Ch\xfa \u0111\u1ec1u l\xe0 ph\xe1 \u0111\u1ecba ng\u1ee5c. Nh\u1eefng ch\xfang sinh \u0111ang ch\u1ecbu kh\u1ed5 trong \u0111\u1ecba ng\u1ee5c \u0111\u1ec1u c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c \u0111\u1ed9. Cho n\xean uy l\u1ef1c c\u1ee7a L\u0103ng Nghi\xeam Ch\xfa ch\xednh l\xe0 l\u1edbn nh\u01b0 v\u1eady \u0111\xf3."],q,q),A.a2(["title","C\u1ea5u Tr\xfac Kh\u1edfi \u0110\u1ea7u C\u1ee7a B\xe0i T\u1ee5ng","meta",r,"preview",'\u0110\u1ec3 b\xe0i tr\xec ch\xfa c\xf3 hi\u1ec7u qu\u1ea3 t\u1ed1t nh\u1ea5t, tuy\u1ec7t \u0111\u1ed1i kh\xf4ng n\xean b\u1ecf qua nghi th\u1ee9c kh\u1edfi \u0111\u1ea7u: Lu\xf4n ph\u1ea3i ni\u1ec7m 3 l\u1ea7n c\xe2u "\u0110\u1ea1i Ph\u1eadt \u0110\u1ea3nh Th\u1ee7 L\u0103ng Nghi\xeam Th\u1ea7n Ch\xfa". C\xe2u n\xe0y gi\u1ed1ng nh\u01b0 c\xe1i \u0111\u1ea7u, ph\u1ea7n th\u1ea7n ch\xfa l\xe0 th\xe2n th\u1ec3; n\u1ebfu kh\xf4ng t\u1ee5ng gi\u1ed1ng nh\u01b0 c\u01a1 th\u1ec3 kh\xf4ng c\xf3 \u0111\u1ea7u.'],q,q),A.a2(["title","S\u1ef1 B\u1ea3o V\u1ec7 C\u1ee7a 8 V\u1ea1n 4 Ng\xe0n Kim Cang T\u1ea1ng","meta",s,"preview","B\u1ea1n t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam, d\xf9 b\u1ea1n ch\u1ec9 t\u1ee5ng m\u1ed9t ch\u1eef, m\u1ed9t c\xe2u, m\u1ed9t h\u1ed9i, hay to\xe0n b\u1ed9, th\xec t\xe1m v\u1ea1n b\u1ed1n ng\xe0n Kim Cang T\u1ea1ng B\u1ed3 T\xe1t c\xf9ng quy\u1ebfn thu\u1ed9c c\u1ee7a c\xe1c ng\xe0i c\u0169ng lu\xf4n lu\xf4n theo b\u1ea3o v\u1ec7 b\u1ea1n c\u1ea9n th\u1eadn, kh\xf4ng \u0111\u1ec3 cho b\u1ea5t k\u1ef3 lo\xe0i ma qu\u1ef7 n\xe0o \u0111\u1ebfn qu\u1ea5y nhi\u1ec5u."],q,q),A.a2(["title","Kh\xf4ng N\xean \u0102n Tr\u1ee9ng Khi Tr\xec Ch\xfa","meta",r,"preview","Kh\xf4ng n\xean \u0103n tr\u1ee9ng khi tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam. Vi\u1ec7c \u0103n tr\u1ee9ng g\xe0 mang t\u1ed9i n\u1eb7ng h\u01a1n c\u1ea3 \u0103n th\u1ecbt th\xf4ng th\u01b0\u1eddng, b\u1edfi l\u1ebd m\u1ed7i qu\u1ea3 tr\u1ee9ng \u0111\u1ea1i di\u1ec7n cho m\u1ed9t sinh m\u1ea1ng nguy\xean v\u1eb9n. \u0102n tr\u1ee9ng mang m\xf9i tanh, ng\u0103n c\u1ea3n th\xe2n t\xe2m \u0111\u1ea1t \u0111\u1ebfn thu\u1ea7n t\u1ecbnh L\u0103ng Nghi\xeam Tam Mu\u1ed9i."],q,q),A.a2(["title","B\u1ea3o Ph\xe1p Ng\u0169 \u0110\u1ea1i T\xe2m Ch\xfa Cho Ng\u01b0\u1eddi B\u1eadn R\u1ed9n","meta",r,"preview","N\u1ebfu kh\xf4ng \u0111\u1ee7 th\u1eddi gian tr\xec to\xe0n b\u1ed9, h\xe3y t\u1ee5ng Ng\u0169 \u0110\u1ea1i T\xe2m Ch\xfa: S\u1ea4T \u0110\xc0N N\u1ec2 \u2014 A CA GIA \u2014 M\u1eacT R\u1eca TR\u1ee4 \u2014 B\xc1T R\u1eca \u0110\xc1T RA GIA \u2014 N\u1ea2NH Y\u1ebeT R\u1eca. Ch\u1ec9 c\u1ea7n tr\xec 7 bi\u1ebfn h\u1eb1ng ng\xe0y, c\xf4ng \u0111\u1ee9c t\u1ea1o ra c\xf2n to l\u1edbn h\u01a1n c\u1ea3 vi\u1ec7c tr\xec t\u1ee5ng \u0111\u1ee7 108 bi\u1ebfn Ch\xfa \u0110\u1ea1i Bi tinh t\u1ea5n."],q,q),A.a2(["title","H\xe0ng Ph\u1ee5c Ma Qu\xe2n","meta",s,"preview","Ch\xfa L\u0103ng Nghi\xeam l\xe0 th\u1ea7n ch\xfa uy l\u1ef1c nh\u1ea5t \u0111\u1ec3 h\xe0ng ph\u1ee5c ma o\xe1n. Khi b\u1ea1n t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam, t\u1ea5t c\u1ea3 t\xe0 ma ngo\u1ea1i \u0111\u1ea1o, y\xeau ma qu\u1ef7 qu\xe1i \u0111\u1ec1u khi\u1ebfp s\u1ee3 v\xe0 kh\xf4ng d\xe1m \u0111\u1ebfn g\u1ea7n. \u0110\xf3 l\xe0 v\xec Ch\xfa L\u0103ng Nghi\xeam ph\xe1t ra h\xe0o quang r\u1ef1c r\u1ee1 c\u1ee7a Ph\u1eadt, soi s\xe1ng kh\u1eafp ph\xe1p gi\u1edbi."],q,q),A.a2(["title","V\u1ee5 Tr\u1ee9ng G\xe0","meta",s,"preview","\u201cB\u1ea1n cho r\u1eb1ng \u0103n chay th\xec \u0103n tr\u1ee9ng c\u0169ng \u0111\u01b0\u1ee3c? C\u0169ng \u0111\u01b0\u1ee3c! Ch\u1edd t\u1edbi khi b\u1ea1n \u0111\u1ea7u thai l\xe0m g\xe0 r\u1ed3i khi \u0111\xf3 b\u1ea1n s\u1ebd hi\u1ec3u (ph\u1eadn l\xe0m g\xe0) ch\xednh do \u0103n tr\u1ee9ng g\xe0 m\xe0 ra\u201d.\n\nH\u1ecfi: L\xe0 \u0111\u1ec7 t\u1eed Ph\u1eadt th\xec c\xf3 th\u1ec3 \u0103n tr\u1ee9ng kh\xf4ng?\n\u0110\xe1p: N\u1ebfu qu\xfd v\u1ecb th\xe8m mu\u1ed1n \u0103n nh\u1eefng th\u1ee9 dinh d\u01b0\u1ee1ng \u0111\xf3, th\xec c\u1ea7n g\xec ph\u1ea3i h\u1ecfi t\xf4i?\n\nH\u1ecfi: T\u1ea1i sao ng\u01b0\u1eddi \u0103n chay kh\xf4ng \u0111\u01b0\u1ee3c \u0103n tr\u1ee9ng?\n\u0110\xe1p: Kh\xf4ng c\xf3 g\xe0 tr\u1ed1ng, g\xe0 m\xe1i c\u0169ng c\xf3 th\u1ec3 \u1ea5p tr\u1ee9ng n\u1edf ra g\xe0 con nh\u01b0 th\u01b0\u1eddng. Ng\xe0y x\u01b0a ng\u01b0\u1eddi ta kh\xf4ng hi\u1ec3u \u0111i\u1ec1u n\xe0y n\xean h\u1ecd n\xf3i l\xe0, n\u1ebfu tr\u1ee9ng kh\xf4ng c\xf3 tr\u1ed1ng th\xec kh\xf4ng th\u1ec3 n\u1edf ra g\xe0 con. Nh\u01b0ng l\u1ed1i n\xf3i n\xe0y c\u0169ng kh\xf4ng \u0111\xfang s\u1ef1 th\u1eadt. B\u1edfi v\xec \u0111\u1ea1o l\xfd v\u1ed1n kh\xf4ng c\xf3 tuy\u1ec7t \u0111\u1ed1i, cho n\xean ch\xfang ta \u0103n chay quy\u1ebft kh\xf4ng n\xean \u0103n tr\u1ee9ng.\n\nH\u1ecfi: L\xfac \u0103n chay c\xf3 th\u1ec3 \u0103n tr\u1ee9ng g\xe0 kh\xf4ng?\n\u0110\xe1p: B\u1ea1n ch\u01b0a \u0103n \u0111\xe3 mu\u1ed1n bi\u1ebft! C\xf9ng v\u1edbi kh\xf4ng \u0103n th\xec th\u1ebf n\xe0o? \u0102n th\xec th\u1ebf n\xe0o?"],q,q),A.a2(["title","S\u1ef1 B\u1ea3o V\u1ec7 C\u1ee7a Ng\xe0n \u0110\xf3a Hoa Sen","meta",s,"preview",'Hai m\u01b0\u01a1i ch\xedn c\xe2u Ch\xfa \u0111\u1ea7u ti\xean, m\u1ed9t khi ni\u1ec7m ra th\xec s\u1ebd xu\u1ea5t hi\u1ec7n m\u1ed9t c\u1ea3nh gi\u1edbi l\xe0: b\u1ed1n m\u1eb7t t\xe1m ph\u01b0\u01a1ng c\xf3 r\u1ea5t nhi\u1ec1u hoa sen \u0111\u1ecf \u0111\u1ebfn \u1ee7ng h\u1ed9 ng\u01b0\u1eddi tr\xec Ch\xfa n\xe0y, cho n\xean n\xf3i: "Ng\xe0n \u0111\xf3a sen \u0111\u1ecf h\u1ed9 ng\u01b0\u1eddi tr\xec." (Thi\xean \u0111\xf3a h\u1ed3ng li\xean h\u1ed9 tr\u1ee5 th\xe2n). T\xe1m v\u1ea1n b\u1ed1n ng\xe0n Kim Cang t\u1ea1ng B\u1ed3 t\xe1t c\u0169ng \u0111\u1ebfn gia h\u1ed9 b\u1ea1n, cho n\xean n\xf3i: "Ng\u1ed3i tr\xean hoa sen \u0111i m\xe2y tr\u1eafng" (T\u1ecda li\xean phi th\u1eeba b\u1ea1ch v\xe2n \u0111\xf4n). C\xe2u Ch\xfa n\xe0y (Nam M\xf4 T\xe1t \u0110\xe1t Tha) v\u1ed1n d\u0129 b\u1ea3o h\u1ed9 ng\u01b0\u1eddi t\u1ee5ng, ai m\xe0 tr\xec c\xe2u Ch\xfa n\xe0y th\xec Ma v\u01b0\u01a1ng Ba Tu\u1ea7n kh\xf4ng c\xf3 c\xe1ch g\xec l\u1ea1i g\u1ea7n \u0111\u01b0\u1ee3c.'],q,q),A.a2(["title","T\u1ea1i Sao Ng\u01b0\u1eddi Ta Mu\u1ed1n T\u1ef1 S\xe1t?","meta",s,"preview","T\xf4i n\xf3i cho qu\xfd v\u1ecb bi\u1ebft, nh\u1eefng ng\u01b0\u1eddi t\u1ef1 s\xe1t \u0111a s\u1ed1 \u0111\u1ec1u b\u1ecb ma qu\u1ef7 k\xeau h\u1ecd \u0111\u1ebfn \u0111\xf3. Con qu\u1ef7 \u0111\xf3 \u0111\u1ed1i v\u1edbi ng\u01b0\u1eddi t\u1ef1 s\xe1t \u0111\xe3 ni\u1ec7m m\u1ed9t b\xe0i ch\xfa. Qu\u1ef7 ni\u1ec7m ch\xfa g\xec? N\xf3 n\xf3i: \u201cM\xe0y \u0111i ch\u1ebft \u0111i! M\xe0y \u0111i ch\u1ebft \u0111i! Ch\u1ebft \u0111i l\xe0 t\u1ed1t l\u1eafm! Ch\u1ebft \u0111i l\xe0 t\u1ed1t nh\u1ea5t \u0111\xf3!\u201d. Con qu\u1ef7 \u0111\xf3 c\xf3 tha t\xe2m th\xf4ng, n\xf3 l\u1ea5y qu\u1ef7 kh\xed x\xe2m nh\u1eadp v\xe0o t\xe2m c\u1ee7a ng\u01b0\u1eddi \u0111\xf3 khi\u1ebfn ng\u01b0\u1eddi \u0111\xf3 ngh\u0129 r\u1eb1ng: \u201cA! Ch\u1ebft \u0111i l\xe0 t\u1ed1t! Ch\u1ebft \u0111i l\xe0 t\u1ed1t!\u201d. Th\u1ebf l\xe0 ng\u01b0\u1eddi \u0111\xf3 b\xe8n \u0111i u\u1ed1ng thu\u1ed1c \u0111\u1ed9c t\u1ef1 t\u1eed, treo c\u1ed5, nh\u1ea3y xu\u1ed1ng bi\u1ec3n... V\xec v\u1eady b\u1ea5t c\u1ee9 l\xfac n\xe0o, m\u1ecdi ng\u01b0\u1eddi c\u1ea7n ph\u1ea3i ni\u1ec7m Ph\u1eadt, ni\u1ec7m ch\xfa. Qu\xfd v\u1ecb ni\u1ec7m Ph\u1eadt ni\u1ec7m ch\xfa th\xec l\xfac \u0111\xf3 c\xf3 Ph\u1eadt quang ph\u1ed5 chi\u1ebfu, ma qu\u1ef7 s\u1ebd b\u1ecf ch\u1ea1y \u0111i m\u1ea5t."],q,q),A.a2(["title","B\u1ed3 T\xe1t Kim Cang T\u1ea1ng \xc2m Th\u1ea7m Th\xfac Gi\u1ee5c","meta",s,"preview","Gi\u1ea3 s\u1eed t\xe2m ni\u1ec7m c\u1ee7a qu\xfd v\u1ecb v\xf4 c\xf9ng t\xe1n lo\u1ea1n, kh\xf4ng th\u1ec3 chuy\xean nh\u1ea5t, nh\u01b0ng n\u1ebfu mi\u1ec7ng c\u1ee7a qu\xfd v\u1ecb li\u1ec1n tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam, th\xec B\u1ed3 T\xe1t Kim Cang T\u1ea1ng V\u01b0\u01a1ng li\u1ec1n d\xf9ng t\xe2m tinh ch\xe2n thu\u1ea7n th\u1ee5c \u0111i theo \xe2m th\u1ea7m th\xfac gi\u1ee5c. Ch\u1eef \u201c\xe2m th\u1ea7m th\xfac gi\u1ee5c\u201d n\xe0y v\xf4 c\xf9ng quan tr\u1ecdng, c\xf3 ngh\u0129a l\xe0 \u1edf ph\xeda sau \xe2m th\u1ea7m \u0111\u1ea9y b\u1ea1n m\u1ed9t c\xe1i, \xe2m th\u1ea7m h\u01b0\u1edbng d\u1eabn b\u1ea1n, nh\u1eafc nh\u1edf b\u1ea1n. Khi\u1ebfn t\xe2m t\xe1n lo\u1ea1n c\u1ee7a qu\xfd v\u1ecb d\u1ea7n m\u1ea5t \u0111i, m\u1ed9t ch\xfat, m\u1ed9t ch\xfat m\u1ed9t sinh ra \u0111\u1ecbnh l\u1ef1c, r\u1ed3i \u0111\u1ea1t \u0111\u01b0\u1ee3c \u0111\u1ecbnh l\u1ef1c, d\u1ea7n d\u1ea7n qu\xfd v\u1ecb s\u1ebd \u0111\u01b0\u1ee3c khai m\u1edf tr\xed hu\u1ec7."],q,q),A.a2(["title","Tr\xec Ch\xfa L\u0103ng Nghi\xeam Nh\u1ea5t T\xe2m","meta",s,"preview","Khi t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam kh\xf4ng n\xean c\xf3 t\xe2m mong c\u1ea7u, kh\xf4ng mong c\u1ea7u \u0111\u1eafc th\u1ea7n th\xf4ng, kh\xf4ng mong c\u1ea7u \u0111\u1eafc Ph\u1eadt nh\xe3n, kh\xf4ng mong c\u1ea7u ti\xeau tai, kh\xf4ng mong c\u1ea7u kh\u1ecfi b\u1ec7nh... Ch\u1ec9 c\u1ea7n nh\u1ea5t t\xe2m t\u1ee5ng tr\xec, th\xec c\xf4ng \u0111\u1ee9c m\u1edbi l\u1edbn. Gi\u1ed1ng nh\u01b0 \u0111\u1ee9a tr\u1ebb b\xfa m\u1eb9, ch\u1ec9 bi\u1ebft b\xfa th\xf4i ch\u1ee9 \u0111\xe2u c\xf3 ngh\u0129 g\xec kh\xe1c. B\xfa no r\u1ed3i th\xec ng\u1ee7, ng\u1ee7 d\u1eady l\u1ea1i b\xfa. Ng\u01b0\u1eddi t\u1ee5ng ch\xfa c\u0169ng ph\u1ea3i nh\u01b0 th\u1ebf, kh\xf4ng \u0111\u01b0\u1ee3c c\xf3 m\u1ed9t v\u1ecdng ni\u1ec7m n\xe0o xen v\xe0o."],q,q),A.a2(["title","Kh\xf4ng \u0102n Ng\u0169 V\u1ecb T\xe2n","meta",s,"preview","\u0110\u1ee9c Ph\u1eadt d\u1ea1y trong Kinh L\u0103ng Nghi\xeam: C\xe1c ch\xfang sinh c\u1ea7u qu\u1ea3 B\u1ed3 \u0110\u1ec1, c\u1ed1t y\u1ebfu l\xe0 kh\xf4ng \u0111\u01b0\u1ee3c \u0103n ng\u0169 v\u1ecb t\xe2n (h\xe0nh, t\u1ecfi, n\xe9n, h\u1eb9, h\u01b0ng h\xe0o). V\xec n\u0103m th\u1ee9 v\u1ecb cay n\xe0y, \u0103n ch\xedn th\xec ph\xe1t d\xe2m, \u0103n s\u1ed1ng th\xec th\xeam ph\u1eabn n\u1ed9. Nh\u1eefng ng\u01b0\u1eddi \u0103n n\u0103m th\u1ee9 v\u1ecb cay n\xe0y, tuy c\xf3 t\u1ee5ng tr\xec m\u01b0\u1eddi hai b\u1ed9 kinh Ph\u1eadt, m\u01b0\u1eddi ph\u01b0\u01a1ng Thi\xean ti\xean c\u0169ng \u0111\u1ec1u ch\xea m\xf9i h\xf4i th\u1ed1i m\xe0 tr\xe1nh xa. C\xe1c ng\u1ea1 qu\u1ef7 s\u1ebd th\u01b0\u1eddng li\u1ebfm m\xf4i mi\u1ec7ng c\u1ee7a ng\u01b0\u1eddi \u1ea5y, do lu\xf4n s\u1ed1ng chung v\u1edbi qu\u1ef7 n\xean ph\u01b0\u1edbc \u0111\u1ee9c ng\xe0y c\xe0ng ti\xeau m\xf2n, ch\u1eb3ng l\u1ee3i \xedch g\xec."],q,q),A.a2(["title","C\u1ea3nh Gi\u1edbi Nhi\u1ec7m M\xe0u","meta",r,"preview",'Khi ni\u1ec7m c\xe2u "Nam M\xf4 L\u0103ng Nghi\xeam H\u1ed9i Th\u01b0\u1ee3ng Ph\u1eadt B\u1ed3 T\xe1t" \u0111\u1ee7 ba l\u1ea7n, tr\xean h\u01b0 kh\xf4ng b\u1ed7ng hi\u1ec7n ra m\u1ed9t \u0110\xe0n th\xe0nh L\u0103ng Nghi\xeam r\u1ed9ng l\u1edbn \u0111\u1ebfn m\u1ee9c kh\xf4ng th\u1ea5y bi\xean gi\u1edbi. \u0110\xe0n th\xe0nh \u1ea5y nh\u01b0 m\u1ed9t c\xe1i \xf4 kh\u1ed5ng l\u1ed3 b\u1eb1ng \xe1nh s\xe1ng bao ph\u1ee7 t\u1eeb tr\xean kh\xf4ng trung xu\u1ed1ng. B\xean trong \u0110\xe0n th\xe0nh c\xf3 v\xf4 s\u1ed1 ch\u01b0 Ph\u1eadt, ch\u01b0 \u0110\u1ea1i B\u1ed3 T\xe1t c\xf9ng t\xe1m v\u1ea1n b\u1ed1n ng\xe0n Kim Cang T\u1ea1ng B\u1ed3 T\xe1t. T\u1ea5t c\u1ea3 c\xe1c Ng\xe0i \u0111\u1ec1u ph\xf3ng ra \u0111\u1ee7 th\u1ee9 h\xe0o quang v\xf4 c\xf9ng r\u1ef1c r\u1ee1 v\xe0 vi di\u1ec7u, chi\u1ebfu r\u1ecdi kh\u1eafp n\u01a1i v\xe0 gia tr\xec cho t\u1ea5t c\u1ea3 m\u1ecdi ng\u01b0\u1eddi. S\u1ef1 hi\u1ec7n di\u1ec7n v\xe0 \xe1nh s\xe1ng t\u1eeb \u0110\xe0n th\xe0nh kh\xf4ng ch\u1ec9 b\u1ea3o v\u1ec7 m\xe0 c\xf2n \u0111em l\u1ea1i l\u1ee3i \xedch l\u1edbn lao cho nh\u1eefng ai th\xe0nh t\xe2m tr\xec t\u1ee5ng, gi\xfap h\u1ecd ti\xeau tr\u1eeb nghi\u1ec7p ch\u01b0\u1edbng, t\xe2m tr\xed thanh t\u1ecbnh v\xe0 ng\xe0y c\xe0ng tinh t\u1ea5n tr\xean con \u0111\u01b0\u1eddng tu h\xe0nh.'],q,q),A.a2(["title","T\xe2m C\u1ee7a Ph\u1eadt - Th\xe2n C\u1ee7a Ph\u1eadt","meta",r,"preview","B\u1ea1ch \xe2n s\u01b0 Ph\u1ed5 Quang! Th\u1ea7n Ch\xfa L\u0103ng Nghi\xeam t\u1ea1i sao l\u1ea1i c\xf3 s\u1ee9c m\u1ea1nh l\u1edbn nh\u01b0 v\u1eady \u1ea1?\nHT. Ph\u1ed5 Quang: Th\u1ea7n Ch\xfa L\u0103ng Nghi\xeam n\xe0y l\xe0 ph\xe1p m\xf4n th\xf9 th\u1eafng nh\u1ea5t trong c\xe1c ph\xe1p m\xf4n. B\u1edfi v\xec n\xf3 ch\xednh l\xe0 t\xe2m c\u1ee7a Ph\u1eadt, l\xe0 th\xe2n c\u1ee7a Ph\u1eadt. Kh\xf4ng c\xf3 th\u1ea7n Ch\xfa L\u0103ng Nghi\xeam, th\xec kh\xf4ng c\xf3 t\u1ea5t c\u1ea3 ch\u01b0 Ph\u1eadt! ... Con ng\u01b0\u1eddi n\u1ebfu th\u1eadt s\u1ef1 hi\u1ec3u \u0111\u01b0\u1ee3c \u0111i\u1ec1u n\xe0y, th\xec \u0111\xe3 kh\xf4ng c\xf2n l\xe0 ph\xe0m phu n\u1eefa r\u1ed3i! Ni\u1ec7m \u0111\u1ee7 36.000 bi\u1ebfn, d\u01b0\u1edbi hai b\xe0n ch\xe2n c\u1ee7a con c\u0169ng c\xf3 hoa sen, khi con \u0111i \u0111\u1ee9ng, th\u1ef1c ra l\xe0 c\xf3 hoa sen n\xe2ng \u0111\u1ee1, ch\u1ec9 l\xe0 nh\u1ee5c nh\xe3n c\u1ee7a con nh\xecn kh\xf4ng th\u1ea5y m\xe0 th\xf4i."],q,q),A.a2(["title","C\u1ea3nh Gi\u1edbi \u0110\u1ea1i T\u1ef1 T\u1ea1i","meta",r,"preview",'C\xf3 c\xe2u: "L\xe0m ng\u01b0\u1eddi th\xec hi\u1ebfm khi kh\u1edd kh\u1ea1o", nh\u01b0ng tu h\xe0nh th\xec ph\u1ea3i \u0111\u1ea3o ng\u01b0\u1ee3c l\u1ea1i! Tu h\xe0nh l\xe0 ph\u1ea3i h\u1ecdc c\xe1ch kh\u1edd kh\u1ea1o... N\u1ebfu nh\u01b0 b\u1ea1n ch\u1eb3ng c\xf3 tr\xed tu\u1ec7, b\u1ea1n s\u1ebd ch\u1eb3ng th\u1ec3 kh\u1edd kh\u1ea1o \u0111\u01b0\u1ee3c. Gi\u1ed1ng nh\u01b0 B\u1ed3 T\xe1t B\u1ed1 \u0110\u1ea1i v\u1eady, Ng\xe0i kh\u1edd nh\u01b0ng m\xe0 Ng\xe0i l\u1ea1i s\u1ed1ng r\u1ea5t sung s\u01b0\u1edbng! S\u1ed1ng tr\xean \u0111\u1eddi \u0111\u1eebng bao gi\u1edd d\u1eb1n v\u1eb7t ng\u01b0\u1eddi kh\xe1c, c\u0169ng \u0111\u1eebng d\u1eb1n v\u1eb7t ch\xednh m\xecnh! Chuy\u1ec7n l\xfac t\xe1m gi\u1edd th\xec \u0111\u1ebfn ch\xedn gi\u1edd l\xe0 ph\u1ea3i qu\xean \u0111i r\u1ed3i. \u0110\u1ec3 nh\u1eefng chuy\u1ec7n phi\u1ec1n n\xe3o \u0111\xf3 trong l\xf2ng l\xe0m chi? Vi\u1ec7c g\xec \u0111\xe3 qua th\xec c\u1ee9 \u0111\u1ec3 n\xf3 qua \u0111i! \u0110\xf3 m\u1edbi l\xe0 Ph\u1eadt, B\u1ed3-t\xe1t, \u0111\xf3 m\u1edbi l\xe0 khai \u0111\u1ea1i ng\u1ed9! Cho n\xean ph\u1ea3i ni\u1ec7m Ch\xfa L\u0103ng Nghi\xeam, ni\u1ec7m Ch\xfa L\u0103ng Nghi\xeam m\u1edbi c\xf3 th\u1ec3 c\xf3 \u0111\u1ecbnh l\u1ef1c, m\u1edbi c\xf3 th\u1ec3 khai m\u1edf tr\xed tu\u1ec7, m\u1ed9t \u0111\u1eddi th\xe0nh Ph\u1eadt \u0111\u1ea1o.'],q,q),A.a2(["title","C\xf4ng \u0110\u1ee9c B\u1eb1ng 10 Toa T\xe0u H\u1ecfa Kinh \u0110\u1ea1i T\u1ea1ng","meta",r,"preview","Kinh \u0110\u1ea1i T\u1ea1ng nhi\u1ec1u nh\u01b0 v\u1eady, ni\u1ec7m t\u1edbi bao gi\u1edd m\u1edbi h\u1ebft? Nh\u01b0ng ni\u1ec7m m\u1ed9t bi\u1ebfn ch\xfa L\u0103ng Nghi\xeam th\xec c\xf4ng \u0111\u1ee9c b\u1eb1ng c\u1ea3 ni\u1ec7m 10 toa t\xe0u h\u1ecfa \u0111\u1ea7y \u1eafp kinh \u0110\u1ea1i T\u1ea1ng! Ai mu\u1ed1n t\u1ee5ng h\u1ebft b\u1ed9 kinh \u0110\u1ea1i T\u1ea1ng th\xec th\xe0 ni\u1ec7m m\u1ed9t bi\u1ebfn ch\xfa L\u0103ng Nghi\xeam c\xf2n h\u01a1n. C\xf3 ng\u01b0\u1eddi tu thi\u1ec1n, c\xf3 ng\u01b0\u1eddi ni\u1ec7m Ph\u1eadt, c\xf3 ng\u01b0\u1eddi tr\xec ch\xfa... c\xf3 t\u1edbi 8 v\u1ea1n 4 ng\xe0n ph\xe1p m\xf4n, nh\u01b0ng cho d\xf9 c\xf3 tu ph\xe1p n\xe0o \u0111i n\u1eefa, c\u0169ng ch\u1eb3ng b\u1eb1ng chuy\xean t\xe2m tu m\u1ed9t m\xecnh ch\xfa L\u0103ng Nghi\xeam. Cho n\xean, ai tu \u0111\u01b0\u1ee3c ch\xfa L\u0103ng Nghi\xeam, ng\u01b0\u1eddi \u0111\xf3 th\u1eadt s\u1ef1 l\xe0 c\xf3 \u0111\u1ea1i ph\xfac b\xe1o!"],q,q),A.a2(["title","Si\xeau \u0110\u1ed9 Cho Ng\u01b0\u1eddi \u0110\xe3 Khu\u1ea5t","meta",r,"preview","C\xf3 ng\u01b0\u1eddi h\u1ecfi v\u1ec1 c\xe1ch si\xeau \u0111\u1ed9 cho ng\u01b0\u1eddi th\xe2n \u0111\xe3 khu\u1ea5t. H\xf2a th\u01b0\u1ee3ng Ph\u1ed5 Quang \u0111\xe1p: Khi v\u1eeba ni\u1ec7m ch\xfa, b\u1ea1n ph\u1ea3i v\u1eeba qu\xe1n t\u01b0\u1edfng l\u1ea1i g\u01b0\u01a1ng m\u1eb7t v\u1edbi ng\u0169 quan \u0111ang m\u1ec9m c\u01b0\u1eddi l\xfac sinh ti\u1ec1n c\u1ee7a ng\u01b0\u1eddi ch\u1ebft. C\u1ee9 nh\u1ea5t t\xe2m ni\u1ec7m nh\u01b0 v\u1eady th\xec d\u01b0\u1edbi ch\xe2n th\u1ea7n th\u1ee9c c\u1ee7a ng\u01b0\u1eddi m\u1ea5t s\u1ebd l\u1eadp t\u1ee9c hi\u1ec7n ra m\u1ed9t \u0111\xf3a hoa sen, ng\u01b0\u1eddi m\u1ea5t t\u1ef1 nhi\xean s\u1ebd nh\u1eadn \u0111\u01b0\u1ee3c l\u1ee3i \xedch si\xeau tho\xe1t."],q,q),A.a2(["title","Ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa Nh\u01b0 \u0110i Thang M\xe1y","meta",r,"preview","M\u1ecdi ng\u01b0\u1eddi c\xf9ng nhau ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa th\xec th\u1ebf gi\u1edbi s\u1ebd b\xecnh y\xean, \u0111\u1ea5t n\u01b0\u1edbc s\u1ebd tai qua n\u1ea1n kh\u1ecfi.\n\nM\u1ed7i b\u1ed9 kinh chia ra r\u1ea5t nhi\u1ec1u ph\u1ea7n. \u0110\u1ecdc c\u1ea3 \u0111\u1eddi c\u0169ng kh\xf4ng h\u1ebft. Nh\u01b0ng L\u0103ng Nghi\xeam Ch\xfa \u0111\xe3 bao g\u1ed3m h\u1ebft t\u1ea5t c\u1ea3 kinh \u0111i\u1ec3n r\u1ed3i. Kinh T\xe2m Kinh ch\xednh l\xe0 ph\u1ea7n tinh t\xfay nh\u1ea5t c\u1ee7a t\u1ea5t c\u1ea3 kinh. L\xe0 \u0111\u1ec3 cho m\xecnh hi\u1ec3u v\xe0 ng\u1ed9 ra.\n\nNi\u1ec7m A Di \u0110\xe0 Ph\u1eadt th\xec tho\xe1t \u0111\u01b0\u1ee3c sinh t\u1eed, nh\u01b0ng ph\u1ea3i th\u1eadt nh\u1ea5t t\xe2m, t\xe2m ph\u1ea3i th\u1eadt s\u1ea1ch. Tham, s\xe2n, si, ki\xeau m\u1ea1n, nghi ng\u1edd... m\u1ed7i ch\u1eef l\xe0 m\u1ed9t c\u1ea3nh. S\u1ebd \u0111\u1ecda v\xe0o \u0111\u01b0\u1eddng A Tu La, \u0111\u01b0\u1eddng ng\u1ea1 qu\u1ef7... r\u01a1i v\xe0o \u0111\u01b0\u1eddng n\xe0o th\xec theo \u0111\u01b0\u1eddng \u0111\xf3.\n\nNi\u1ec7m \u0110\u1ea1i Bi Ch\xfa 108 l\u1ea7n c\u0169ng kh\xf4ng b\u1eb1ng ni\u1ec7m 1 l\u1ea7n L\u0103ng Nghi\xeam Ch\xfa. Kh\xf4ng b\u1eb1ng ni\u1ec7m 7 l\u1ea7n Ng\u0169 \u0110\u1ea1i T\xe2m Ch\xfa. \u0110\u1ea1i Bi Ch\xfa l\xe0 \u0111\u1ec3 c\u1ee9u kh\u1ed5. Ni\u1ec7m \u0111\u1ebfn m\u1ee9c cao nh\u1ea5t th\xec to\xe0n th\xe2n s\xe1ng l\xean, c\xf3 th\u1ec3 th\xe0nh B\u1ed3 T\xe1t, nh\u01b0ng v\u1eabn ch\u01b0a th\xe0nh Ph\u1eadt \u0111\u01b0\u1ee3c. Mu\u1ed1n th\xe0nh Ph\u1eadt th\xec ph\u1ea3i ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa n\xe0y.\n\nNi\u1ec7m kinh kh\xe1c th\xec ph\u1ea3i h\u1ed3i h\u01b0\u1edbng. Nh\u01b0ng ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa n\xe0y v\xe0 Kinh Kim Cang th\xec kh\xf4ng c\u1ea7n h\u1ed3i h\u01b0\u1edbng. \u0110\u1ee9c Ph\u1eadt \u0111\xe3 \u1ea5n ch\u1ee9ng r\u1ed3i. Kh\xf4ng c\u1ea7n ph\u1ea3i l\xe0m th\xeam n\u1eefa. Ni\u1ec7m L\u0103ng Nghi\xeam Ch\xfa, m\u1ed9t \u0111\u1eddi n\xe0y l\xe0 th\xe0nh Ph\u1eadt.\n\nNi\u1ec7m L\u0103ng Nghi\xeam Ch\xfa gi\u1ed1ng nh\u01b0 \u0111i thang m\xe1y v\u1eady \u0111\xf3. V\xc8O m\u1ed9t c\xe1i l\xe0 th\xe0nh Ph\u1eadt r\u1ed3i!"],q,q),A.a2(["title","\u0110\u1ed9ng T\u1eeb Bi","meta",r,"preview","\u0110\u1ed9ng T\u1eeb Bi, t\u1eeb x\u01b0a \u0111\u1ebfn nay kh\xf4ng bi\u1ebft \u0111\xe3 c\xf3 bao nhi\xeau v\u1ecb \u0111\u1ea1i \u0111\u1ee9c (b\u1eadc tu h\xe0nh cao th\xe2m) \u0111\u1ebfn \u0111\xe2y \u0111\xf3ng c\u1eeda \u1ea9n tu r\u1ed3i. S\u01b0 ph\u1ee5 l\xe0 h\xf2a th\u01b0\u1ee3ng Ph\u1ed5 Quang k\u1ec3 l\u1ea1i r\u1eb1ng, nh\u1eefng gi\u1ecdt n\u01b0\u1edbc r\u1ec9 ra t\u1eeb khe \u0111\xe1 trong \u0111\u1ed9ng ch\xednh l\xe0 n\u01b0\u1edbc m\u1eaft c\u1ee7a Ph\u1eadt B\u1ed3 T\xe1t. N\u01b0\u1edbc n\xe0y c\xf3 th\u1ec3 u\u1ed1ng ch\u1ee9 kh\xf4ng \u0111\u01b0\u1ee3c l\xe3ng ph\xed, v\xe0 c\xf2n ch\u1eefa \u0111\u01b0\u1ee3c b\xe1ch b\u1ec7nh. C\u0103n nh\xe0 \u0111\xe1 nh\u1ecf nh\u1eafn, gi\u1ea3n d\u1ecb kia ch\xednh l\xe0 n\u01a1i h\xf2a th\u01b0\u1ee3ng Ph\u1ed5 Quang t\u1eebng tu h\xe0nh l\xfac c\xf2n tr\u1ebb. Th\u1eddi D\xe2n Qu\u1ed1c, c\xe1c v\u1ecb h\xf2a th\u01b0\u1ee3ng n\u1ed5i ti\u1ebfng nh\u01b0 ng\xe0i H\u01b0 V\xe2n, ph\xe1p s\u01b0 Vi\xean Anh, v\xe0 h\xf2a th\u01b0\u1ee3ng Lai Qu\u1ea3 c\u0169ng \u0111\u1ec1u t\u1eebng tu h\xe0nh \u1edf n\u01a1i n\xe0y."],q,q),A.a2(["title","TH\u1ea6N CH\xda KHAI M\u1ede TR\xcd TU\u1ec6","meta",s,"preview","V\u1ea5n \u0111\xe1p c\xf9ng Ho\xe0 Th\u01b0\u1ee3ng Tuy\xean Ho\xe1 v\xe0o ng\xe0y 10 th\xe1ng 01 n\u0103m 1993\n\nt\u1ea1i H\u1ecdc Vi\u1ec7n C\xf4ng Nghi\u1ec7p K\u1ef9 Thu\u1eadt Qu\u1ed1c L\u1eadp - \u0110\xe0i Loan\n\nPhi\xean d\u1ecbch b\u1edfi Vi\u1ec7n D\u1ecbch Kinh Qu\u1ed1c T\u1ebf\n\nhttps://www.drbachinese.org/vbs/publish/453/vbs453p020.pdf\n\nH\u1ecfi: Con l\xe0 m\u1ed9t \u0111\u1ec7 t\u1eed, v\xe0 con r\u1ea5t th\xedch \u0111\u1ecdc nh\u1eefng s\xe1ch c\u1ee7a H\xf2a Th\u01b0\u1ee3ng. Con c\xf3 m\u1ed9t c\xe2u h\u1ecfi quan tr\u1ecdng nh\u01b0 sau. H\xf2a Th\u01b0\u1ee3ng \u0111\xe3 \u0111\u1ec1 c\u1eadp r\u1eb1ng c\xf3 hai c\xe2u ch\xfa trong Ch\xfa L\u0103ng Nghi\xeam c\xf3 th\u1ec3 khai m\u1edf tr\xed tu\u1ec7 cho ch\xfang ta. Xin Ho\xe0 Th\u01b0\u1ee3ng h\xe3y n\xf3i cho ch\xfang con bi\u1ebft \u0111\xf3 l\xe0 hai c\xe2u ch\xfa n\xe0o? T\u1ea1 \u01a1n s\u1ef1 t\u1eeb bi ch\u1ec9 d\u1eabn c\u1ee7a ng\xe0i. Nam M\xf4 \u0110\u1ea1i T\u1eeb \u0110\u1ea1i Bi Qu\xe1n Th\u1ebf \xc2m B\u1ed3 T\xe1t.\n\n\u0110\xe1p: \u0110\xfang v\u1eady, ta c\xf3 th\u1ec3 n\xf3i cho qu\xfd v\u1ecb, nh\u01b0ng tin hay kh\xf4ng tin l\xe0 t\xf9y qu\xfd v\u1ecb. Ta c\u0169ng kh\xf4ng th\u1ec3 t\xf9y ti\u1ec7n n\xf3i cho qu\xfd v\u1ecb nghe. Tr\u01b0\u1edbc h\u1ebft qu\xfd v\u1ecb h\xe3y cho ta bi\u1ebft l\xe0 qu\xfd v\u1ecb c\xf3 th\xe0nh th\u1eadt ni\u1ec7m hay kh\xf4ng? N\u1ebfu ta n\xf3i cho qu\xfd v\u1ecb nghe, r\u1ed3i qu\xfd v\u1ecb c\u0169ng qu\xean m\u1ea5t, \u0111\u1ed3ng th\u1eddi c\u0169ng kh\xf4ng t\u1ee5ng ni\u1ec7m. Qua m\u1ed9t th\u1eddi gian, qu\xfd v\u1ecb l\u1ea1i h\u1ecfi: \u201cXin S\u01b0 Ph\u1ee5 n\xf3i cho con bi\u1ebft hai c\xe2u ch\xfa n\xe0y, cho \u0111\u1ebfn b\xe2y gi\u1edd con v\u1eabn ch\u01b0a khai tr\xed tu\u1ec7.\u201d T\u1ea1i sao tr\xed tu\u1ec7 c\u1ee7a qu\xfd v\u1ecb ch\u01b0a khai m\u1edf? L\xe0 do qu\xfd v\u1ecb kh\xf4ng t\u1ee5ng ni\u1ec7m, v\u1eady th\xec l\xe0m sao tr\xed tu\u1ec7 c\u1ee7a qu\xfd v\u1ecb c\xf3 th\u1ec3 khai m\u1edf \u0111\u01b0\u1ee3c? Do \u0111\xf3, n\u1ebfu qu\xfd v\u1ecb mu\u1ed1n h\u1ecdc hai c\xe2u Th\u1ea7n ch\xfa n\xe0y, th\xec nh\u1ea5t \u0111\u1ecbnh ph\u1ea3i nh\u1ea5t t\xe2m d\u1ee5ng c\xf4ng t\u1ee5ng ni\u1ec7m, th\u1eadm ch\xed kh\xf4ng \u0103n c\u0169ng \u0111\u01b0\u1ee3c nh\u01b0ng kh\xf4ng th\u1ec3 kh\xf4ng ni\u1ec7m Th\u1ea7n ch\xfa n\xe0y, th\u1eadm ch\xed kh\xf4ng m\u1eb7c \u0111\u1ed3 c\u0169ng \u0111\u01b0\u1ee3c nh\u01b0ng kh\xf4ng th\u1ec3 kh\xf4ng ni\u1ec7m Th\u1ea7n ch\xfa n\xe0y, th\u1eadm ch\xed kh\xf4ng ng\u1ee7 c\u0169ng \u0111\u01b0\u1ee3c nh\u01b0ng kh\xf4ng th\u1ec3 kh\xf4ng ni\u1ec7m Th\u1ea7n ch\xfa n\xe0y. N\u1ebfu qu\xfd v\u1ecb c\xf3 quy\u1ebft t\xe2m nh\u01b0 v\u1eady, th\xec tr\xed tu\u1ec7 c\u1ee7a qu\xfd v\u1ecb ch\u1eafc ch\u1eafn s\u1ebd khai m\u1edf. N\u1ebfu qu\xfd v\u1ecb kh\xf4ng c\xf3 \u0111\u01b0\u1ee3c quy\u1ebft t\xe2m nh\u01b0 v\u1eady m\xe0 ch\u1ec9 mu\u1ed1n t\xecm c\u01a1 h\u1ed9i \u0111i \u0111\u01b0\u1eddng t\u1eaft, mong ta ch\u1ec9 gi\xe1o v\xe0i c\xe2u, r\u1ed3i ngh\u0129 r\u1eb1ng nh\u01b0 th\u1ebf l\xe0 c\xf3 \u0111\u01b0\u1ee3c b\u1ea3o b\u1ed1i, th\xec r\u1ed1t cu\u1ed9c qu\xfd v\u1ecb c\u0169ng ch\u1eb3ng \u0111\u01b0\u1ee3c g\xec c\u1ea3.\n\nB\xe2y gi\u1edd th\xec ta c\xf3 th\u1ec3 gi\u1ea3i th\xedch m\u1ed9t ch\xfat. Hai c\xe2u ch\xfa n\xe0y l\xe0:\n\n\u201cTh\u1ec9nh c\u1ea7u ch\u01b0 Ph\u1eadt v\xe0 ch\u01b0 v\u1ecb B\u1ed3 T\xe1t khai m\u1edf tr\xed tu\u1ec7, khai m\u1edf tr\xed tu\u1ec7 ch\xe2n ch\xe1nh, kh\xf4ng ph\u1ea3i tr\xed tu\u1ec7 th\u1ebf gian. Khi\u1ebfn con c\xf3 th\u1ec3 nh\u1eadn th\u1ee9c r\xf5 t\u1ea5t c\u1ea3 c\xe1c Ph\xe1p v\xe0 phi Ph\xe1p. C\xf3 \u0111\u01b0\u1ee3c Tr\u1ea1ch Ph\xe1p Nh\xe3n (m\u1eaft ch\u1ecdn Ph\xe1p).\u201d\n\nCh\xfa n\xe0y \u0111\u01b0\u1ee3c n\xf3i ra b\u1edfi Ho\xe1 Ph\u1eadt tr\xean \u0111\u1ea3nh \u0111\u1ea7u (V\xf4 Ki\u1ebfn \u0110\u1ea3nh T\u01b0\u1edbng) c\u1ee7a Ph\u1eadt Th\xedch Ca M\xe2u Ni. B\u1edfi v\u1eady m\u1ed7i c\xe2u ch\xfa n\xe0y \u0111\u1ec1u l\xe0 nh\u1eefng linh v\u0103n, \u0111\u1ec1u l\xe0 ch\xe2n ng\xf4n di\u1ec7u ng\u1eef, do \u0111\xf3 hai c\xe2u ch\xfa n\xe0y n\xf3i r\u1eb1ng, \u201cTh\u1ec9nh ch\u01b0 Ph\u1eadt v\xe0 ch\u01b0 v\u1ecb B\u1ed3 T\xe1t, xin h\xe3y gia h\u1ed9 cho con, khi\u1ebfn con \u0111\u01b0\u1ee3c khai m\u1edf \u0111\u1ea1i tr\xed tu\u1ec7.\u201d\n\n\xdd ngh\u0129a c\u1ee7a Th\u1ea7n ch\xfa n\xe0y c\u0169ng g\u1ecdi l\xe0 \u201cch\xe2n ng\xf4n\u201d, c\u0169ng g\u1ecdi l\xe0 \u201clinh v\u0103n\u201d.\n\nT\u1ea1i sao g\u1ecdi l\xe0 \u201cch\xe2n ng\xf4n\u201d? B\u1edfi v\xec Th\u1ea7n ch\xfa n\xe0y kh\xf4ng c\xf3 m\u1ed9t ch\xfat gi\u1ea3 d\u1ed1i n\xe0o c\u1ea3.\n\nT\u1ea1i sao g\u1ecdi l\xe0 \u201clinh v\u0103n\u201d? B\u1edfi v\xec Th\u1ea7n ch\xfa n\xe0y v\u1ed1n l\xe0 c\u1ee7a tr\u1eddi Ph\u1ea1m Thi\xean v\xe0 \u0111\u01b0\u1ee3c \u0110\u1ee9c Ph\u1eadt Th\xedch Ca M\xe2u Ni d\xf9ng ch\xfa n\xe0y \u0111\u1ec3 gi\u1ea3i c\u1ee9u ng\xe0i A-nan. Do \u0111\xf3 m\u1ed9t s\u1ed1 ng\u01b0\u1eddi kh\xf4ng bi\u1ebft c\xe1ch \u0111\u1ec3 s\u1eed d\u1ee5ng Th\u1ea7n ch\xfa n\xe0y. Ta l\u1ea1i n\xf3i th\xeam cho qu\xfd v\u1ecb nghe r\u1eb1ng t\u1eeb l\xfac ta c\xf2n nh\u1ecf, ta \u0111\xe3 \u0111i kh\u1eafp n\u01a1i h\xe0ng ph\u1ee5c y\xeau ma v\xe0 b\u1eaft qu\u1ef7 qu\xe1i. Nh\u1eefng lo\xe0i y\xeau ma qu\u1ef7 qu\xe1i c\xf3 th\u1ec3 bi\u1ebfn h\xf3a th\xe0nh ng\u01b0\u1eddi. ta \u0111\xe3 g\u1eb7p h\u01a1n m\u1ed9t tr\u0103m lo\u1ea1i n\xe0y. Ch\xfang \u0111i \u0111\xe2u l\xe0 h\u1ea1i ng\u01b0\u1eddi \u0111\u1ebfn \u0111\xf3, v\xec th\u1ebf ta \u0111\xe3 d\xf9ng Ch\xfa L\u0103ng Nghi\xeam \u0111\u1ec3 h\xe0ng ph\u1ee5c ch\xfang. K\u1ebft cu\u1ed9c l\xe0 t\u1ea5t c\u1ea3 y\xeau ma qu\u1ef7 qu\xe1i \u0111\u1ec1u mu\u1ed1n c\xf9ng ta nh\u1ea5t quy\u1ebft t\u1eed chi\u1ebfn, v\xec v\u1eady phi\u1ec1n ph\u1ee9c l\u1ea1i k\xe9o \u0111\u1ebfn, g\xe2y ra r\u1ea5t nhi\u1ec1u r\u1eafc r\u1ed1i. Do nh\xe2n duy\xean \u0111\xf3, nay tu\u1ed5i ta \u0111\xe3 l\u1edbn, c\xf3 l\u1ebd c\u0169ng \u0111\xe3 t\u1eebng tr\u1ea3i, n\xean kh\xf4ng c\xf2n mu\u1ed1n tranh \u0111\u1ea5u v\u1edbi ch\xfang.\n\nNh\xe2n v\xec:\n\nTranh l\xe0 ph\xe2n th\u1eafng b\u1ea1i,\n\n\u0110i ng\u01b0\u1ee3c l\u1ea1i v\u1edbi \u0110\u1ea1o.\n\nTrong T\xe2m sanh b\u1ed1n t\u01b0\u1edbng,\n\nL\xe0m sao v\xe0o Tam Mu\u1ed9i (\u0110\u1ecbnh)? (1)\n\nTam Mu\u1ed9i, ch\xednh l\xe0 Ch\xe1nh \u0110\u1ecbnh, Ch\xe1nh Th\u1ecd. Khi ch\xfang ta c\xf9ng ng\u01b0\u1eddi tranh ch\u1ea5p, t\u1ee9c l\xe0 c\xf3 t\xe2m h\u01a1n thua: ho\u1eb7c ta th\u1eafng ng\u01b0\u1eddi thua, ho\u1eb7c ta thua ng\u01b0\u1eddi th\u1eafng. T\xe2m tranh th\u1eafng b\u1ea1i \u1ea5y ch\xednh l\xe0 \u201c\u0110i ng\u01b0\u1ee3c l\u1ea1i v\u1edbi \u0110\u1ea1o\u201d. V\xec ng\u01b0\u1ee3c l\u1ea1i v\u1edbi \u0110\u1ea1o, t\xe2m sanh kh\u1edfi b\u1ed1n t\u01b0\u1edbng: ng\xe3 t\u01b0\u1edbng, nh\xe2n t\u01b0\u1edbng, ch\xfang sanh t\u01b0\u1edbng, th\u1ecd gi\u1ea3 t\u01b0\u1edbng.\n\nKhi b\u1ed1n t\u01b0\u1edbng hi\u1ec7n ti\u1ec1n, l\xe0m sao c\xf3 \u0111\u01b0\u1ee3c \u0111\u1ecbnh l\u1ef1c? L\xe0m sao c\xf3 th\u1ec3 ch\u1ee9ng \u0111\u1eafc Ch\xe1nh \u0110\u1ecbnh, Ch\xe1nh Th\u1ecd?\n\nCho n\xean, b\u1ea5t lu\u1eadn vi\u1ec7c g\xec, ch\xfang ta c\u0169ng kh\xf4ng n\xean d\xf9ng b\u1ea1o l\u1ef1c \u0111\u1ec3 gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1, m\xe0 c\u1ea7n ph\u1ea3i gi\u1ea3i quy\u1ebft trong tinh th\u1ea7n h\xf2a b\xecnh. Kh\xf4ng n\xean tr\xean d\u01b0\u1edbi c\xf9ng nhau tranh l\u1ee3i, m\xe0 ch\xfang ta c\u1ea7n ph\u1ea3i d\xf9ng h\xf2a kh\xed, t\u1eeb bi \u0111\u1ec3 \u0111\u1ed1i \u0111\xe3i.\n\nN\u1ebfu m\u1ed9t qu\u1ed1c gia, m\u1ecdi ng\u01b0\u1eddi \u0111\u1ec1u h\xf2a thu\u1eadn, c\xf3 h\xf2a kh\xed, th\xec qu\u1ed1c gia \u1ea5y nh\u1ea5t \u0111\u1ecbnh s\u1ebd h\u01b0ng th\u1ecbnh. C\xf2n n\u1ebfu su\u1ed1t ng\xe0y tranh \u0111\u1ea5u, k\u1ebb n\xe0y gi\xe0nh c\u1ee7a k\u1ebb kia, ng\u01b0\u1eddi n\xe0y \u0111\xe1nh m\u1eafng ng\u01b0\u1eddi kia, th\xec th\u1eadt ch\u1eb3ng t\u1ed1t \u0111\u1eb9p, ch\u1eb3ng c\xe1t t\u01b0\u1eddng ch\xfat n\xe0o c\u1ea3.\n\nGhi ch\xfa:\n\nNguy\xean v\u0103n Hoa ng\u1eef:\n\n(1)\n\n\u722d\u662f\u52dd\u8ca0\u5fc3\uff0c\n\n\u8207\u9053\u76f8\u9055\u80cc\uff0c\n\n\u4fbf\u751f\u56db\u76f8\u5fc3,\n\n\u7531\u4f55\u5f97\u4e09\u6627\uff1f\n\nTranh th\u1ecb th\u1eafng ph\u1ee5 t\xe2m,\n\nD\u1eef \u0111\u1ea1o t\u01b0\u01a1ng vi b\u1ed1i\uff0c\n\nTi\u1ec7n sanh t\u1ee9 t\u01b0\u01a1ng t\xe2m\uff0c\n\nDo h\xe0 \u0111\u1eafc tam mu\u1ed9i\uff1f"],q,q),A.a2(["title","TH\u1eacT S\u1ef0 C\xd3 TH\u1ec2 TR\xcc CH\xda L\u0102NG NGHI\xcaM, TRONG H\u01af KH\xd4NG LI\u1ec0N C\xd3 M\u1ed8T \u0110\u1ea0I B\u1ea0CH T\xc1N C\xc1I, C\xd3 OAI TH\u1ea6N L\u1ef0C \u201cPH\u1ed4 \u1ea4M MU\xd4N PH\u01af\u01a0NG\u201d!","meta",s,"preview","Tuy\xean C\xf4ng Th\u01b0\u1ee3ng Nh\xe2n khai th\u1ecb\n\n\u201cThi\xean t\xe1n c\xe1i v\xe2n\u201d: \u201cThi\xean t\xe1n c\xe1i v\xe2n\u201d ngh\u0129a l\xe0 h\u01b0\u01a1ng m\xe0 b\u1ea1n \u0111\u1ed1t k\u1ebft t\u1ee5 gi\u1eefa h\u01b0 kh\xf4ng, h\xecnh th\xe0nh m\u1ed9t c\xe1i l\u1ecdng gi\u1ed1ng nh\u01b0 chi\u1ebfc d\xf9, che ph\u1ee7 v\xe0 b\u1ea3o h\u1ed9 ch\xfang sinh. Trong Ch\xfa L\u0103ng Nghi\xeam c\xf3 \u0110\u1ea1i B\u1ea1ch T\xe1n C\xe1i. Khi b\u1ea1n t\u1ee5ng ch\xfa n\xe0y, trong h\u01b0 kh\xf4ng li\u1ec1n hi\u1ec7n ra m\u1ed9t \u0110\u1ea1i B\u1ea1ch T\xe1n C\xe1i. N\u01a1i \u0111\u01b0\u1ee3c \u0110\u1ea1i B\u1ea1ch T\xe1n C\xe1i che ph\u1ee7 th\xec kh\xf4ng c\xf3 c\xe1c lo\u1ea1i tai n\u1ea1n, kh\xf4ng c\xf3 \u0111\u1ed9ng \u0111\u1ea5t, kh\xf4ng c\xf3 thi\xean tai, t\u1ea5t c\u1ea3 tai n\u1ea1n \u0111\u1ec1u kh\xf4ng x\u1ea3y \u0111\u1ebfn!\n\nCh\u1eef \u201cC\xe1i\u201d trong c\xe2u \u201cch\u1ea5p tr\xec nh\u1ea5t c\xe1i\u201d, theo M\u1eadt t\xf4ng, ch\xednh l\xe0 ch\u1ec9 \u0110\u1ea1i B\u1ea1ch T\xe1n C\xe1i trong Ch\xfa L\u0103ng Nghi\xeam. Trong Ch\xfa L\u0103ng Nghi\xeam c\xf3 ch\xfa t\xe2m \u2014 \u201c\u6089\u601b\u591a\u9262\u601b\u56c9\u201d (T\u1ea5t \u0110\xe1t \u0110a B\xe1t \u0110\xe1t La). S\xe1u ch\u1eef n\xe0y ch\xednh l\xe0 ch\xfa t\xe2m. N\u1ebfu nh\u1ea5t t\xe2m chuy\xean ch\xfa, t\xe2m kh\xf4ng t\u1ea1p ni\u1ec7m, ch\xed th\xe0nh tr\xec t\u1ee5ng th\xec trong h\u01b0 kh\xf4ng c\xf3 th\u1ec3 hi\u1ec7n ra m\u1ed9t \u0110\u1ea1i B\u1ea1ch T\xe1n C\xe1i. \u0110\u1ea1i B\u1ea1ch T\xe1n C\xe1i \u1ea5y c\xf3 oai th\u1ea7n l\u1ef1c \u201cph\u1ed5 \u1ea5m mu\xf4n ph\u01b0\u01a1ng\u201d, t\u1ee9c che ch\u1edf kh\u1eafp m\u1ecdi ph\u01b0\u01a1ng.\n\nPh\xe0m n\u01a1i n\xe0o \u0111\u01b0\u1ee3c n\xf3 che ph\u1ee7 th\xec \u0111ao binh kh\xf4ng kh\u1edfi, \xf4n d\u1ecbch kh\xf4ng sinh, n\u01b0\u1edbc l\u1eeda v\xe0 tr\u1ed9m c\u01b0\u1edbp \u0111\u1ec1u d\u1ee9t s\u1ea1ch; ch\u1ec9 c\xf3 nh\u01b0 \xfd c\xe1t t\u01b0\u1eddng, m\u01b0a thu\u1eadn gi\xf3 h\xf2a, nh\xe2n d\xe2n an l\u1ea1c, kh\xf4ng c\xf3 b\u1ea5t k\u1ef3 tai n\u1ea1n n\xe0o.\n\nN\u1ebfu n\xf3i theo gi\xe1o ph\xe1p, ch\u1eef \u201cc\xe1i\u201d n\xe0y ch\xednh l\xe0 di\u1ec7u ph\xe1p c\u1ee7a th\u1eadt t\u01b0\u1edbng. Th\u1eadt t\u01b0\u1edbng kh\xf4ng c\xf3 t\u01b0\u1edbng, nh\u01b0ng l\u1ea1i kh\xf4ng g\xec ch\u1eb3ng ph\u1ea3i t\u01b0\u1edbng. T\u1eeb th\u1eadt t\u01b0\u1edbng m\xe0 sinh ra t\u1ea5t c\u1ea3 c\xe1c ph\xe1p, d\xf9ng t\u1ea5t c\u1ea3 c\xe1c ph\xe1p \u0111\u1ec3 gi\xe1o h\xf3a ch\xfang sinh trong ch\xedn ph\xe1p gi\u1edbi. \u0110\xe2y ch\xednh l\xe0 \u0111\u1ea1o l\xfd:\n\n\u201cM\u1ed9t g\u1ed1c ph\xe2n t\xe1n th\xe0nh mu\xf4n h\xecnh v\u1ea1n tr\u1ea1ng, mu\xf4n h\xecnh v\u1ea1n tr\u1ea1ng cu\u1ed1i c\xf9ng v\u1eabn quy v\u1ec1 m\u1ed9t g\u1ed1c.\u201d\n\nTr\xec t\u1ee5ng c\xe2u ch\xfa t\xe2m n\xe0y th\xec tr\xean \u0111\u1ec9nh \u0111\u1ea7u s\u1ebd c\xf3 c\xe1c lo\u1ea1i b\u1ea3o c\xe1i h\u1ed9 tr\xec b\u1ea1n.\n\n\u201c\u6089\u601b\u591a\u9262\u601b\u56c9\u201d (T\u1ea5t \u0110\xe1t \u0110a B\xe1t \u0110\xe1t La) l\xe0 ch\xfa t\xe2m c\u1ee7a Ch\xfa L\u0103ng Nghi\xeam, cho n\xean c\xf3 ng\u01b0\u1eddi th\u01b0\u1eddng xuy\xean tr\xec t\u1ee5ng c\xe2u ch\xfa n\xe0y. Tr\xec t\u1ee5ng c\xe2u ch\xfa n\xe0y th\xec c\xf3 c\xe1c lo\u1ea1i b\u1ea3o c\xe1i; trong \u0111\xf3 ch\u1ee7 y\u1ebfu l\xe0 d\u1ef1ng n\xean \u0110\u1ea1i B\u1ea1ch T\xe1n C\xe1i.\n\nCh\xfang ta m\u1ed7i ng\xe0y c\xf3 th\u1ec3 tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam, ch\xednh l\xe0 \u0111ang gi\xfap \u0111\u1ee1 to\xe0n th\u1ebf gi\u1edbi, khi\u1ebfn tai n\u1ea1n tr\xean to\xe0n th\u1ebf gi\u1edbi c\xf3 th\u1ec3 gi\u1ea3m b\u1edbt m\u1ed9t ph\u1ea7n, nghi\u1ec7p ma c\u0169ng gi\u1ea3m b\u1edbt m\u1ed9t ph\u1ea7n. V\xec v\u1eady, Ch\xfa L\u0103ng Nghi\xeam v\xf4 c\xf9ng quan tr\u1ecdng!\n\nB\u1ea3o c\xe1i c\xf3 r\u1ea5t nhi\u1ec1u lo\u1ea1i, cho n\xean n\xf3i l\xe0 c\xe1c lo\u1ea1i b\u1ea3o c\xe1i; l\u1ea1i c\xf3 c\xe1c lo\u1ea1i m\xe2y h\u01b0\u01a1ng, m\xe2y hoa, ch\u1ee9 kh\xf4ng ph\u1ea3i ch\u1ec9 c\xf3 m\u1ed9t lo\u1ea1i. Nh\u1eefng b\u1ea3o c\xe1i, m\xe2y h\u01b0\u01a1ng v\xe0 m\xe2y hoa n\xe0y th\u01b0\u1eddng \u1edf tr\xean \u0111\u1ec9nh \u0111\u1ea7u b\u1ea1n \u0111\u1ec3 h\u1ed9 tr\xec b\u1ea1n. V\xec th\u1ebf, r\u1ea5t nhi\u1ec1u vi\u1ec7c v\u1ed1n c\xf3 v\u1ea5n \u0111\u1ec1 c\u0169ng tr\u1edf th\xe0nh kh\xf4ng c\xf3 v\u1ea5n \u0111\u1ec1; d\xf9 c\xf3 chuy\u1ec7n b\u1ea5t ng\u1edd c\u0169ng kh\xf4ng x\u1ea3y ra tai n\u1ea1n. \u0110\xe2y l\xe0 s\u1ef1 l\u1ee3i \xedch \u0111\u1ed1i v\u1edbi t\u1ea5t c\u1ea3 m\u1ecdi ng\u01b0\u1eddi tr\xean th\u1ebf gi\u1edbi.\n\nV\xec v\u1eady, ch\xfang ta tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam ch\xednh l\xe0 \u0111ang gi\xfap \u0111\u1ee1 th\u1ebf gi\u1edbi, khi\u1ebfn th\u1ebf gi\u1edbi gi\u1ea3m b\u1edbt nh\u1eefng tai n\u1ea1n nh\u01b0 tai n\u1ea1n h\xe0ng kh\xf4ng, tai n\u1ea1n giao th\xf4ng. Ch\u1eb3ng h\u1ea1n nh\u01b0 tai n\u1ea1n t\xe0u h\u1ecfa, tai n\u1ea1n \xf4 t\xf4, tai n\u1ea1n m\xe1y bay, xe bu\xfdt, th\u1eadm ch\xed c\u1ea3 chi\u1ebfn tranh, \u0111\u1ea1n ph\xe1o \u2014 nh\u1eefng tai n\u1ea1n \u1ea5y \u0111\u1ec1u c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c \xe2m th\u1ea7m h\xf3a gi\u1ea3i. \u0110\u1ed3ng th\u1eddi c\u0169ng ti\xeau tr\u1eeb tai ch\u01b0\u1edbng c\u1ee7a ch\xfang sinh. Khi tai ch\u01b0\u1edbng kh\xf4ng c\xf2n, con ng\u01b0\u1eddi li\u1ec1n \u0111\u01b0\u1ee3c b\xecnh an. \u0110\xe2y ch\xednh l\xe0 l\u1ee3i \xedch cho qu\u1ea7n ch\xfang.\n\nB\u1ea1n c\xf3 th\u1ec3 m\u1ed7i ng\xe0y m\u1ed9t gi\xe2y c\u0169ng kh\xf4ng gi\xe1n \u0111o\u1ea1n tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam, nh\u1ea5t \u0111\u1ecbnh s\u1ebd c\xf3 \u0111\u1ea1i c\u1ea3m \u1ee9ng. Ch\u1ec9 c\u1ea7n kh\xf4ng gi\xe1n \u0111o\u1ea1n; kh\xf4ng gi\xe1n \u0111o\u1ea1n ch\xednh l\xe0 Tam-mu\u1ed9i.\n\nCh\u01b0 Ph\u1eadt c\xf3 n\u0103m b\u1ed9:\n\nPh\u01b0\u01a1ng \u0110\xf4ng: Kim Cang B\u1ed9\n\nPh\u01b0\u01a1ng Nam: B\u1ea3o Sinh B\u1ed9\n\nPh\u01b0\u01a1ng T\xe2y: Li\xean Hoa B\u1ed9\n\nPh\u01b0\u01a1ng B\u1eafc: Y\u1ebft Ma B\u1ed9\n\nTrung \u01b0\u01a1ng: Ph\u1eadt B\u1ed9\n\n\u201c\u6089\u601b\u591a\u9262\u601b\u56c9\u201d (T\u1ea5t \u0110\xe1t \u0110a B\xe1t \u0110\xe1t La) l\xe0 ph\xe1p c\u1ee7a Ph\u1eadt B\u1ed9 Trung \u01b0\u01a1ng, cho n\xean c\xf3 th\u1ec3 nhi\u1ebfp ph\u1ee5c n\u0103m \u0111\u1ea1i ma qu\xe2n.\n\nN\u1ebfu kh\xf4ng c\xf3 ch\u01b0 Ph\u1eadt n\u0103m ph\u01b0\u01a1ng, n\u0103m \u0111\u1ea1i ma qu\xe2n s\u1ebd ng\xe0y ng\xe0y tung ho\xe0nh tr\xean th\u1ebf gi\u1edbi \u2014 ch\xfang ngang d\u1ecdc kh\xf4ng ki\xeang n\u1ec3, kh\xf4ng ch\xfat e d\xe8. May thay c\xf3 ch\u01b0 Ph\u1eadt \u1edf n\u0103m ph\u01b0\u01a1ng \xe2m th\u1ea7m tr\u1ea5n ph\u1ee5c ch\xfang, n\xean ch\xfang kh\xf4ng d\xe1m c\xf4ng khai ho\xe0nh h\xe0nh.\n\nB\u1ea5t lu\u1eadn l\xe0 lo\u1ea1i y\xeau ma qu\u1ef7 qu\xe1i n\xe0o, thi\xean ma hay ngo\u1ea1i \u0111\u1ea1o, t\u1ea5t c\u1ea3 \u0111\u1ec1u ph\u1ea3i thu\u1eadn theo s\u1ee9c m\u1ea1nh c\u1ee7a Ch\xfa L\u0103ng Nghi\xeam. N\u1ebfu kh\xf4ng thu\u1eadn theo th\xec s\u1ebd b\u1ecb ti\xeau di\u1ec7t. Ch\xfa L\u0103ng Nghi\xeam c\xf3 ph\xe1p l\u1ef1c ti\xeau di\u1ec7t v\xe0 ph\xe1 tan t\u1ea5t c\u1ea3 ma qu\xe2n.\n\nV\xec v\u1eady, ng\u01b0\u1eddi bi\u1ebft tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam, thi\xean ma ngo\u1ea1i \u0111\u1ea1o v\xe0 t\u1ea5t c\u1ea3 qu\u1ef7 qu\xe1i \u0111\u1ec1u s\u1ee3 b\u1ea1n. N\u1ebfu ch\xfang kh\xf4ng s\u1ee3, cu\u1ed1i c\xf9ng ch\xfang v\u1eabn s\u1ebd b\u1ecb h\xe0ng ph\u1ee5c d\u01b0\u1edbi s\u1ee9c m\u1ea1nh c\u1ee7a b\u1ea1n."],q,q),A.a2(["title","BU\xd4NG V\xd5 C\xd4NG, V\xc0O CHUNG NAM S\u01a0N \u0102N L\xc1 C\xc2Y 72 N\u0102M","meta",r,"preview",'1. V\xcc SAO KH\xd4NG LUY\u1ec6N V\xd5 N\u1eeeA?\nV\u1ec1 sau, L\xe3o H\xf2a Th\u01b0\u1ee3ng nh\u1eadn ra:\n"V\xf5 c\xf4ng c\xf3 cao \u0111\u1ebfn m\u1ea5y c\u0169ng kh\xf4ng th\xe0nh \u0111\u1ea1o \u0111\u01b0\u1ee3c, m\xe0 c\xf2n d\u1ec5 l\xe0m t\u1ed5n th\u01b0\u01a1ng ng\u01b0\u1eddi.\nNh\xecn th\u1ea5y chuy\u1ec7n b\u1ea5t b\xecnh l\xe0 mu\u1ed1n xen v\xe0o.\nK\u1ebft qu\u1ea3 l\xe0 \u0111\u1ec3 c\u1ee9u 1 ng\u01b0\u1eddi t\u1ed1t, c\xf3 th\u1ec3 ph\u1ea3i l\xe0m t\u1ed5n th\u01b0\u01a1ng 100 ng\u01b0\u1eddi x\u1ea5u.\nOan oan t\u01b0\u01a1ng b\xe1o \u0111\u1ebfn bao gi\u1edd m\u1edbi d\u1ee9t?"\n\nNg\xe0i quy\u1ebft \u0111\u1ecbnh kh\xf4ng luy\u1ec7n n\u1eefa.\nNg\xe0i n\xf3i: "Ng\u01b0\u1eddi \u0111\u1ebfn 30 tu\u1ed5i m\xe0 c\xf2n luy\u1ec7n v\xf5 c\xf4ng l\xe0 ch\u1ea5p m\xea b\u1ea5t ng\u1ed9.\nC\xf4ng phu ph\u1ea3i luy\u1ec7n t\u1eeb nh\u1ecf. V\xf5 c\xf4ng c\xf3 cao \u0111\u1ebfn m\u1ea5y c\u0169ng kh\xf4ng tho\xe1t \u0111\u01b0\u1ee3c sinh t\u1eed."\n\nT\u1eeb \u0111\xf3 Ng\xe0i tr\u1ed1n v\xe0o r\u1eebng s\xe2u. Kh\xf4ng ti\u1ebfp x\xfac v\u1edbi ai.\nChuy\u1ec7n b\u1ea5t b\xecnh kh\xf4ng nh\xecn th\u1ea5y, c\u0169ng kh\xf4ng c\xf3 c\u01a1 h\u1ed9i "g\xe2y s\u1ef1" n\u1eefa.\n\n2. \u0110I B\u1ed8 M\u1ea4Y TH\xc1NG \u0110\u1ebeN CHUNG NAM S\u01a0N\nV\u1ec1 sau nghe n\xf3i Chung Nam S\u01a1n l\xe0 th\xe1nh \u0111\u1ecba m\xe0 bao \u0111\u1eddi hi\u1ec1n nh\xe2n \u1ea9n s\u0129 tu h\xe0nh \u0111\u1eafc \u0111\u1ea1o.\nNg\xe0i li\u1ec1n d\u1eabn \u0111\u1ec7 t\u1eed \u0111i. \u0110i b\u1ed9 m\u1ea5y th\xe1ng m\u1edbi t\u1edbi.\n\nL\xfac \u0111\xf3 c\u1ecdp m\xf9 \u0111\xe3 ch\u1ebft, tinh v\u1eabn c\xf2n s\u1ed1ng.\nTh\u1ea5y Ng\xe0i thu d\u1ecdn y v\xe0 thi\u1ec1n tr\u01b0\u1ee3ng \u0111\u1ecbnh \u0111i, n\xf3 \xf4m ch\xe2n Ng\xe0i kh\xf3c, kh\xf4ng cho \u0111i.\nL\xe3o H\xf2a Th\u01b0\u1ee3ng \u0111\xe0nh nh\xe2n l\xfac tinh ng\u1ee7, c\u1ea7m thi\u1ec1n tr\u01b0\u1ee3ng v\xe0 y, l\xe9n r\u1eddi \u0111i.\n\n3. 72 N\u0102M \u0102N L\xc1 C\xc2Y V\u1ece C\xc2Y\nChung Nam S\u01a1n kh\xe1c v\u1edbi Tr\u01b0\u1eddng B\u1ea1ch S\u01a1n.\nKh\xf4ng c\xf3 c\xe2y \u0103n qu\u1ea3, \u0111\u1ea5t l\u1ea1i x\u1ea5u.\n2 th\u1ea7y tr\xf2 kh\xf4ng c\xf3 qu\u1ea3 r\u1eebng \u0111\u1ec3 \u0103n, c\u0169ng kh\xf4ng th\u1ec3 tr\u1ed3ng khoai nh\u01b0 \u1edf Tr\u01b0\u1eddng B\u1ea1ch \u0111\u1ec3 \u0111\u1ee1 \u0111\xf3i.\n\nNh\u01b0ng Ng\xe0i v\u1eabn nh\u1edb l\u1eddi T\u1ed5 d\u1ea1y: kh\xf4ng ti\u1ebfp x\xfac v\u1edbi ng\u01b0\u1eddi.\nNg\xe0y ng\xe0y ng\u1ed3i trong hang tr\xec ch\xfa tu h\xe0nh.\nH\xe8 \u0103n l\xe1 c\xe2y, \u0111\xf4ng \u0103n v\u1ecf c\xe2y. \u0102n nh\u01b0 v\u1eady 72 n\u0103m.\n\u0102n \u0111\u1ee7 72 lo\u1ea1i l\xe1 c\xe2y v\xe0 v\u1ecf c\xe2y.\n\nM\xe3i \u0111\u1ebfn cu\u1ed1i n\u0103m 1996 m\u1edbi c\xf3 c\u01b0 s\u0129 B\u1eafc Kinh l\xean n\xfai g\u1eedi g\u1ea1o.\n\nL\xfac \u0111\xf3 d\xe2n r\u1ea5t ngh\xe8o. N\xf4ng d\xe2n l\xe0m qu\u1ea7n qu\u1eadt c\u1ea3 ng\xe0y m\u1edbi ki\u1ebfm \u0111\u01b0\u1ee3c 2 xu.\nL\u01b0\u01a1ng th\u1ef1c c\u0169ng \xedt. L\xe3o H\xf2a Th\u01b0\u1ee3ng kh\xf4ng bao gi\u1edd \u0111\u1ebfn nh\xe0 d\xe2n "h\xf3a duy\xean".\nL\xe1 c\xe2y kh\xf4 \u0111\u1ed1t th\xe0nh tro, h\xf2a v\u1edbi n\u01b0\u1edbc l\u1ea1nh u\u1ed1ng cho no b\u1ee5ng.\n\nNg\xe0i n\xf3i: "72 lo\u1ea1i c\xe2y \u0111\u1ec1u \u0103n \u0111\u01b0\u1ee3c. Ch\u1ec9 c\u1ea7n gi\xe3 l\xe1 v\xe0 th\xe2n c\xe2y th\xe0nh b\u1ed9t, n\u1ea5u ch\xedn l\xe0 \u0103n \u0111\u01b0\u1ee3c. R\u1ea5t b\u1ed5."\nNg\xe0i n\xf3i: "T\u1ea5t c\u1ea3 do t\xe2m t\u1ea1o. Con n\xf3i n\xf3 l\xe0 l\xe1 c\xe2y v\u1ecf c\xe2y th\xec n\xf3 l\xe0 l\xe1 c\xe2y v\u1ecf c\xe2y. Con n\xf3i n\xf3 l\xe0 b\xe1nh m\xec th\xec n\xf3 l\xe0 b\xe1nh m\xec."\n"Ch\u1ec9 c\u1ea7n b\u1ee5ng kh\xf4ng k\xeau \u1ee5c \u1ee5c, ru\u1ed9t kh\xf4ng d\xednh v\xe0o nhau, ng\u1ed3i thi\u1ec1n \u0111\u01b0\u1ee3c l\xe0 \u0111\u01b0\u1ee3c r\u1ed3i."'],q,q),A.a2(["title","Tr\xec Ch\xfa C\u1ea7n Ch\xed Th\xe0nh Chuy\xean Nh\u1ea5t","meta",r,"preview",'Ph\u1ed5 Quang L\xe3o H\xf2a Th\u01b0\u1ee3ng\nTr\xedch t\u1eeb "Chung Nam S\u01a1n Quan \xc2m C\u1ed5 \u0110\u1ed9ng Khai Th\u1ecb L\u1ee5c"\n\nChuy\u1ec7n tr\xec ch\xfa , quan tr\u1ecdng nh\u1ea5t ch\xednh l\xe0 4 ch\u1eef \u300eCh\xed Th\xe0nh Chuy\xean Nh\u1ea5t\u300f!\n\nC\xe1c Ph\u1eadt t\u1eed th\u1ea5y kh\xf4ng, Th\u1ea7y h\u01a1n 100 tu\u1ed5i r\u1ed3i m\xe0 m\u1ed7i ng\xe0y v\u1eabn th\xe0nh th\u1eadt ni\u1ec7m ch\xfa. V\xec sao? V\xec th\u1ea7y bi\u1ebft ch\xfa n\xe0y linh nghi\u1ec7m l\u1eafm.\n\nTh\u1ebf n\xe0o l\xe0 Ch\xed Th\xe0nh Chuy\xean Nh\u1ea5t? Th\u1ea7y n\xf3i cho c\xe1c Ph\u1eadt t\u1eed nghe:\nTh\u1ee9 nh\u1ea5t - T\xe2m ph\u1ea3i th\xe0nh, \u0111\u1eebng c\xf3 l\u0103ng x\u0103ng.\nMi\u1ec7ng th\xec ni\u1ec7m ch\xfa m\xe0 t\xe2m l\u1ea1i ngh\u0129 chuy\u1ec7n kh\xe1c, g\u1ecdi l\xe0 \u300emi\u1ec7ng ni\u1ec7m t\xe2m kh\xf4ng theo\u300f, v\u1eady th\xec v\xf4 \xedch!\n\nTh\u1ee9 hai - Ph\u1ea3i chuy\xean nh\u1ea5t m\u1ed9t m\xf4n.\n\u0110\u1eebng h\xf4m nay ni\u1ec7m ch\xfa n\xe0y, ng\xe0y mai \u0111\u1ed5i ch\xfa kh\xe1c. C\u1ea3 \u0111\u1eddi th\u1ea7y ch\u1ec9 tr\xec m\u1ed9t b\u1ed9 L\u0103ng Nghi\xeam Ch\xfa, \u0111\xe3 h\u01a1n 80 n\u0103m r\u1ed3i.\n\nTh\u1ee9 ba - Ph\u1ea3i m\u1ed9t l\xf2ng m\u1ed9t d\u1ea1, ki\xean \u0111\u1ecbnh.\nD\xf9 tr\u1eddi c\xf3 s\u1eadp xu\u1ed1ng th\u1ea7y v\u1eabn ng\u1ed3i ni\u1ec7m ch\xfa.\n\nC\xe1c Ph\u1eadt t\u1eed xem c\xe1i am tranh c\u1ee7a th\u1ea7y \u0111\xf3, ch\u1eb3ng c\xf3 g\xec h\u1ebft, ch\u1ec9 c\xf3 m\u1ed7i c\xe1i gi\u01b0\u1eddng v\xe1n. T\u1ea1i sao? L\xe0 \u0111\u1ec3 c\u1eaft \u0111\u1ee9t v\u1ecdng t\u01b0\u1edfng! \u1ede \u0111\xe2y ngo\xe0i vi\u1ec7c ni\u1ec7m ch\xfa ra th\xec kh\xf4ng ngh\u0129 g\xec kh\xe1c.\n\nC\xf3 ng\u01b0\u1eddi h\u1ecfi th\u1ea7y: \u300eB\u1ea1ch L\xe3o H\xf2a Th\u01b0\u1ee3ng, H\xf2a Th\u01b0\u1ee3ng ni\u1ec7m ch\xfa c\xf3 th\u1ea5y c\u1ea3nh gi\u1edbi g\xec kh\xf4ng \u1ea1?\u300f\nTh\u1ea7y tr\u1ea3 l\u1eddi: \u300eTh\u1ea7y ch\u1eb3ng th\u1ea5y c\u1ea3nh gi\u1edbi g\xec c\u1ea3, ch\u1ec9 bi\u1ebft th\xe0nh th\u1eadt m\xe0 ni\u1ec7m th\xf4i!\u300f\nC\xe1c Ph\u1eadt t\u1eed nh\u1edb nha: \u0110\u1eebng c\xf3 mong c\u1ea7u c\u1ea3nh gi\u1edbi, c\xe0ng c\u1ea7u l\xe0 c\xe0ng b\u1ecb ma ch\u01b0\u1edbng. C\u1ee9 th\xe0nh th\u1eadt ni\u1ec7m, t\u1ef1 nhi\xean s\u1ebd c\xf3 l\u1ee3i \xedch.\n\nTh\u1ea7y m\u1ed7i ng\xe0y 3 gi\u1edd r\u01b0\u1ee1i s\xe1ng l\xe0 th\u1ee9c d\u1eady. L\u1ea1y Ph\u1eadt 100 l\u1ea1y tr\u01b0\u1edbc, r\u1ed3i b\u1eaft \u0111\u1ea7u tr\xec ch\xfa. M\u1ed9t ng\xe0y \xedt nh\u1ea5t 108 bi\u1ebfn, d\xf9 m\u01b0a hay n\u1eafng c\u0169ng kh\xf4ng b\u1ecf.\nV\xec sao ph\u1ea3i v\u1eady? V\xec chuy\u1ec7n sinh t\u1eed r\u1ea5t l\u1edbn, v\xf4 th\u01b0\u1eddng \u0111\u1ebfn nhanh l\u1eafm!\n\nB\xe2y gi\u1edd c\xf3 nhi\u1ec1u ng\u01b0\u1eddi v\u1eeba ni\u1ec7m ch\xfa v\u1eeba b\u1ea5m \u0111i\u1ec7n tho\u1ea1i. V\u1eady g\u1ecdi l\xe0 tr\xec ch\xfa g\xec? \u0110\xf3 l\xe0 gi\u1ee1n ch\u01a1i \u0111\xf3!\n\u0110\xe3 ni\u1ec7m th\xec ph\u1ea3i ni\u1ec7m cho nghi\xeam t\xfac. Kh\xf4ng ni\u1ec7m th\xec th\xf4i. Ph\u1eadt B\u1ed3 T\xe1t kh\xf4ng g\u1ea1t ai bao gi\u1edd, ch\u1ec9 c\xf3 m\xecnh t\u1ef1 g\u1ea1t m\xecnh th\xec kh\xf4ng ai c\u1ee9u \u0111\u01b0\u1ee3c.\n\nCu\u1ed1i c\xf9ng th\u1ea7y t\u1eb7ng c\xe1c Ph\u1eadt t\u1eed m\u1ed9t c\xe2u:\n\u300e\u0110\xe1nh tan v\u1ecdng t\u01b0\u1edfng, th\xec ph\xe1p th\xe2n s\u1ebd hi\u1ec3n l\u1ed9\u300f\n= Khi n\xe0o qu\xfd v\u1ecb d\u1eb9p \u0111\u01b0\u1ee3c h\u1ebft v\u1ecdng t\u01b0\u1edfng trong \u0111\u1ea7u, th\xec t\xe1nh Ph\u1eadt c\u1ee7a qu\xfd v\u1ecb s\u1ebd s\u1ed1ng l\u1ea1i. L\xfac \u0111\xf3 tr\xec ch\xfa m\u1edbi linh nghi\u1ec7m!'],q,q),A.a2(["title","MU\u1ed0N NHANH CH\xd3NG TH\xc0NH T\u1ef0U, H\xc3Y T\u1ee4NG THU\u1ed8C CH\xda L\u0102NG NGHI\xcaM","meta",r,"preview","L\u1eddi H\xf2a th\u01b0\u1ee3ng Ph\u1ed5 Quang\n\nNi\u1ec7m A Di \u0110\xe0 Ph\u1eadt, sau m\u1ed9t tr\u0103m l\u1ebb t\xe1m ngh\xecn n\u0103m s\u1ebd th\xe0nh Ph\u1eadt, nh\u1ea5t \u0111\u1ecbnh s\u1ebd th\xe0nh Ph\u1eadt! \u0110\u1ee9c A Di \u0110\xe0 t\u1eeb bi, ng\u01b0\u1eddi n\xe0o ni\u1ec7m danh hi\u1ec7u Ng\xe0i \u0111\u1ec1u c\xf3 th\u1ec3 th\xe0nh Ph\u1eadt. Nh\u01b0ng n\u1ebfu b\u1ea1n mu\u1ed1n nhanh ch\xf3ng th\xe0nh t\u1ef1u, h\xe3y hi\u1ebfu thu\u1eadn v\u1edbi cha m\u1eb9 v\xe0 t\u1ee5ng thu\u1ed9c Ch\xfa L\u0103ng Nghi\xeam.\n\nT\u1ea1i sao khi t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam l\u1ea1i ph\u1ea3i ph\xe1t \xe2m vang r\xf5?\n\nN\u1ebfu \xe2m thanh qu\xe1 nh\u1ecf th\xec qu\u1ef7 th\u1ea7n c\xf2n kh\xf4ng nghe th\u1ea5y, v\u1eady b\u1ea1n \u0111\u1ed9 ai?\n\n\xc2m thanh l\u1edbn, ngay c\u1ea3 c\xe1c lo\xe0i c\xf4n tr\xf9ng, ki\u1ebfn c\u0169ng c\xf3 th\u1ec3 nghe \u0111\u01b0\u1ee3c m\xe0 k\u1ebft duy\xean th\xe0nh Ph\u1eadt. \u0110\u1ed3ng th\u1eddi, vi\u1ec7c tr\xec t\u1ee5ng c\xf2n c\xf3 th\u1ec3 l\xe0m ti\xeau tr\u1eeb nh\u1eefng v\u1ecdng ni\u1ec7m c\u1ee7a ch\xednh m\xecnh, khi\u1ebfn v\u1ecdng ni\u1ec7m kh\xf4ng th\u1ec3 qu\u1ea5y nhi\u1ec5u t\xe2m t\xednh, h\xe0ng ph\u1ee5c c\u01a1n bu\u1ed3n ng\u1ee7, khai th\xf4ng kinh m\u1ea1ch, b\u1ed5 sung d\u01b0\u01a1ng kh\xed v\xe0 t\u0103ng c\u01b0\u1eddng th\u1ec3 ch\u1ea5t.\n\nN\u0102M \u0110\u1ea0I T\xc2M CH\xda:\n\n\u53f1\u9640\u4f60 / S\u1ea4T \u0110\xc0 N\u1ec2\n\u963f\u8fe6\u56c9 / A CA LA\n\u5bc6\u550e\u67f1 / M\u1eacT R\u1eca TR\u1ee4\n\u822c\u550e\u601b\u56c9\u8036 / B\xc1T R\u1eca \u0110\xc1T RA DA\n\u511c\u63ed\u550e / N\u1ea2NH Y\u1ebeT R\u1eca\n\nBa ch\u1eef l\xe0 m\u1ed9t c\xe2u. N\u0103m c\xe2u n\xe0y bi\u1ec3u th\u1ecb Ng\u0169 ph\u01b0\u01a1ng Ph\u1eadt h\xe0ng ph\u1ee5c Ng\u0169 ph\u01b0\u01a1ng ma.\n\nT\xf4i n\xf3i \u0111\xe2y l\xe0 t\xe2m ch\xfa ch\xednh th\u1ed1ng c\u1ee7a Ch\xfa L\u0103ng Nghi\xeam (\u0111\u1ea1i t\xe2m ch\xfa). C\xf3 ng\u01b0\u1eddi n\xf3i t\xe2m ch\xfa c\u1ee7a Ch\xfa L\u0103ng Nghi\xeam l\xe0 c\xe2u cu\u1ed1i c\xf9ng, t\u1ee9c c\xe2u ch\xfa t\xe2m. T\xe2m ch\xfa c\u1ee7a Ch\xfa L\u0103ng Nghi\xeam ch\xednh th\u1ed1ng ch\xednh l\xe0 tr\xe1i tim c\u1ee7a ch\u01b0 Ph\u1eadt. Ch\xednh c\xe2u n\xe0y c\xf3 n\u0103ng l\u1ef1c khi\u1ebfn thi\xean h\u1ea1 h\xf2a b\xecnh.\n\nCh\xfa L\u0103ng Nghi\xeam ch\xednh l\xe0 do \u0110\u1ee9c Ph\u1eadt Th\xedch Ca M\xe2u Ni tuy\xean thuy\u1ebft. \xc2n \u0111\u1ee9c c\u1ee7a Ph\u1eadt th\u1eadt kh\xf3 b\xe1o \u0111\xe1p. Ch\xfa L\u0103ng Nghi\xeam c\xf2n li\xean quan \u0111\u1ebfn s\u1ef1 h\u01b0ng suy c\u1ee7a to\xe0n th\u1ec3 Ph\u1eadt gi\xe1o, li\xean quan \u0111\u1ebfn h\u1ebft th\u1ea3y ch\xfang sinh. Trong tr\u1eddi \u0111\u1ea5t n\xe0y, kh\xf4ng c\xf3 g\xec quan tr\u1ecdng h\u01a1n Ch\xfa L\u0103ng Nghi\xeam.\n\nV\xec v\u1eady, ch\u1ec9 c\u1ea7n t\xf4i c\xf2n m\u1ed9t h\u01a1i th\u1edf, t\xf4i v\u1eabn s\u1ebd h\u1ebft l\xf2ng ho\u1eb1ng d\u01b0\u01a1ng th\u1ea7n ch\xfa L\u0103ng Nghi\xeam n\xe0y.\n\nT\u1ea5t c\u1ea3 m\u1ecdi th\u1ee9 tr\xean th\u1ebf gian \u0111\u1ec1u l\xe0 gi\u1ea3, ngay c\u1ea3 th\xe2n th\u1ec3 c\u1ee7a l\xe3o Ph\u1ed5 Quang t\xf4i \u0111\xe2y c\u0169ng l\xe0 gi\u1ea3. Ch\u1ec9 c\xf3 Ch\xfa L\u0103ng Nghi\xeam l\xe0 ch\xe2n th\u1eadt nh\u1ea5t. V\xec v\u1eady, t\xf4i ngay c\u1ea3 ch\xednh m\xecnh c\u0169ng kh\xf4ng tin, ch\u1ec9 tin v\xe0o Ch\xfa L\u0103ng Nghi\xeam n\xe0y.\n\nCho n\xean, khi m\u1ecdi ng\u01b0\u1eddi tham gia ph\xe1p h\u1ed9i th\u1ea5t nh\u1eadt, m\u1ed7i ng\xe0y tr\xec t\u1ee5ng th\u1ea7n ch\xfa, nh\u1ea5t \u0111\u1ecbnh ph\u1ea3i d\xf9ng t\xe2m m\xe0 ni\u1ec7m, ph\u1ea3i \u0111em t\xe2m ch\xe2n th\xe0nh ra \u0111\u1ec3 tr\xec t\u1ee5ng. \u0110\u1eebng v\u1eeba ni\u1ec7m v\u1eeba kh\u1edfi v\u1ecdng t\u01b0\u1edfng, v\u1eeba ni\u1ec7m v\u1eeba nghi ng\u1edd.\n\nB\u1ea1n xem, khi t\xf4i v\u1eeba ni\u1ec7m Ch\xfa L\u0103ng Nghi\xeam th\xec ngay c\u1ea3 l\xe3o Ph\u1ed5 Quang t\xf4i c\u0169ng kh\xf4ng c\xf2n n\u1eefa. To\xe0n t\xe2m \u0111\u1ec1u h\xf2a nh\u1eadp v\xe0o vi\u1ec7c tr\xec ch\xfa.\n\nKhi t\u1ee5ng thu\u1ed9c c\xe2u tr\u01b0\u1edbc th\xec ngh\u0129 \u0111\u1ebfn c\xe2u ti\u1ebfp theo; t\u1ee5ng \u0111\u1ebfn ch\u1eef tr\u01b0\u1edbc th\xec ngh\u0129 \u0111\u1ebfn ch\u1eef ti\u1ebfp theo. C\u1ee9 nh\u01b0 v\u1eady, nh\u1ea5t t\xe2m b\u1ea5t lo\u1ea1n m\xe0 tr\xec t\u1ee5ng th\u1ea7n ch\xfa. C\u1ee9 b\xe1m ch\u1eb7t l\u1ea5y Ch\xfa L\u0103ng Nghi\xeam, kh\xf4ng bu\xf4ng b\u1ecf, th\xec trong \u0111\u1eddi n\xe0y nh\u1ea5t \u0111\u1ecbnh c\xf3 th\u1ec3 th\xe0nh t\u1ef1u."],q,q),A.a2(["title","NI\u1ec6M CH\xda L\u0102NG NGHI\xcaM B\u1ea2Y NG\xc0Y, C\u0102N B\u1ec6NH L\u1ea0 B\u1ed6NG NHI\xcaN KH\u1eceI H\u1eb2N","meta",s,"preview",'\u5ba3\u5316\u4e0a\u4eba - Tuy\xean H\xf3a Th\u01b0\u1ee3ng Nh\xe2n:\nT\xf4i k\u1ec3 cho c\xe1c b\u1ea1n nghe m\u1ed9t c\xe2u chuy\u1ec7n c\xf3 th\u1eadt th\u1ebf n\xe0y: \u1ede v\xf9ng \u0110\xf4ng B\u1eafc Trung Qu\u1ed1c, c\xf3 m\u1ed9t ng\u01b0\u1eddi m\u1eafc ph\u1ea3i c\u0103n b\u1ec7nh l\u1ea1, bao nhi\xeau b\xe1c s\u0129 \u0111\u1ec1u ch\u1eefa kh\xf4ng kh\u1ecfi. Sau \u0111\xf3, \xf4ng \u1ea5y g\u1eb7p \u0111\u01b0\u1ee3c m\u1ed9t v\u1ecb l\xe3o tu h\xe0nh d\u1ea1y cho c\xe1ch ni\u1ec7m Ch\xfa L\u0103ng Nghi\xeam. \xd4ng \u1ea5y \u0111\xe3 th\xe0nh t\xe2m th\xe0nh \xfd ni\u1ec7m su\u1ed1t b\u1ea3y ng\xe0y, v\xe0 b\u1ec7nh t\xecnh li\u1ec1n kh\u1ecfi h\u1eb3n! \u0110\xe2y kh\xf4ng ph\u1ea3i l\xe0 m\xea t\xedn, m\xe0 ch\xednh l\xe0 uy th\u1ea7n l\u1ef1c c\u1ee7a Ch\xfa L\u0103ng Nghi\xeam!\n\nNg\u01b0\u1eddi tr\xec t\u1ee5ng Ch\xfa L\u0103ng Nghi\xeam th\xec \u0111i \u0111\u1ebfn \u0111\xe2u c\u0169ng c\xf3 thi\u1ec7n th\u1ea7n h\u1ed9 ph\xe1p \u0111i theo b\u1ea3o v\u1ec7. C\xe1c b\u1ea1n nh\xecn T\u1ebf C\xf4ng H\xf2a Th\u01b0\u1ee3ng xem, t\u1ea1i sao ng\xe0i l\u1ea1i c\xf3 th\u1ec3 h\xe0ng y\xeau ph\u1ee5c ma? Ch\xednh l\xe0 d\u1ef1a v\xe0o s\u1ee9c m\u1ea1nh c\u1ee7a Ch\xfa L\u0103ng Nghi\xeam! Th\u1ea7n ch\xfa n\xe0y v\u1eeba ni\u1ec7m l\xean m\u1ed9t c\xe1i l\xe0 y\xeau ma qu\u1ef7 qu\xe1i \u0111\u1ec1u s\u1ee3 h\xe3i m\xe0 ch\u1ea1y tr\u1ed1n th\u1eadt xa.\n\nTh\u1ebf nh\u01b0ng, c\xe1c b\u1ea1n \u0111\u1eebng c\xf3 ngh\u0129 r\u1eb1ng h\u1ec5 ni\u1ec7m v\xe0i bi\u1ebfn l\xe0 c\xf3 \u0111\u1ea1i th\u1ea7n th\xf4ng ngay nh\xe9. Th\u1eddi tr\u1ebb khi t\xf4i ni\u1ec7m Ch\xfa L\u0103ng Nghi\xeam, ni\u1ec7m \u0111\u1ebfn m\u1ee9c r\u1ed9p c\u1ea3 mi\u1ec7ng ra m\xe0 v\u1eabn ti\u1ebfp t\u1ee5c ni\u1ec7m. T\u1ea1i sao v\u1eady? B\u1edfi v\xec t\xf4i bi\u1ebft c\xf4ng \u0111\u1ee9c c\u1ee7a th\u1ea7n ch\xfa n\xe0y l\xe0 kh\xf4ng th\u1ec3 ngh\u0129 b\xe0n!\n\nB\xe2y gi\u1edd c\xf3 r\u1ea5t nhi\u1ec1u ng\u01b0\u1eddi c\u1ee9 mong c\u1ea7u c\u1ea3m \u1ee9ng, ni\u1ec7m \u0111\u01b0\u1ee3c v\xe0i ng\xe0y kh\xf4ng th\u1ea5y h\xe0o quang c\u1ee7a Ph\u1eadt hi\u1ec7n ra l\xe0 li\u1ec1n b\u1ecf kh\xf4ng ni\u1ec7m n\u1eefa. Nh\u01b0 v\u1eady th\xec g\u1ecdi g\xec l\xe0 tu h\xe0nh? Kinh L\u0103ng Nghi\xeam n\xf3i r\u1ea5t r\xf5 r\xe0ng: "N\u1ebfu kh\xf4ng tr\xec gi\u1edbi, d\u1eabu c\xf3 t\u1ee5ng ch\xfa, chung quy c\u0169ng kh\xf4ng ph\u1ea3i l\xe0 ch\xednh \u0111\u1ecbnh." B\u1ea1n v\u1eeba \u0103n th\u1ecbt u\u1ed1ng r\u01b0\u1ee3u, l\u1ea1i v\u1eeba ni\u1ec7m ch\xfa, th\xec l\xe0m sao m\xe0 c\xf3 hi\u1ec7u qu\u1ea3 cho \u0111\u01b0\u1ee3c?\n\nH\xe3y nh\u1edb k\u1ef9 l\u1eddi n\xe0y c\u1ee7a t\xf4i: Tr\xec Ch\xfa L\u0103ng Nghi\xeam th\xec ph\u1ea3i gi\u1ed1ng nh\u01b0 \u0103n c\u01a1m v\u1eady, m\u1ed9t ng\xe0y c\u0169ng kh\xf4ng th\u1ec3 thi\u1ebfu. S\xe1ng ni\u1ec7m, t\u1ed1i ni\u1ec7m, \u0111i \u0111\u01b0\u1eddng ni\u1ec7m, ng\u1ed3i xe ni\u1ec7m, h\xe3y ni\u1ec7m b\xe0i ch\xfa n\xe0y v\xe0o t\u1eadn trong t\xe2m c\u1ee7a m\xecnh. C\u1ee9 ni\u1ec7m nh\u01b0 v\u1eady su\u1ed1t ba n\u0103m, b\u1ea1n s\u1ebd t\u1ef1 bi\u1ebft c\xe1i l\u1ee3i \xedch c\u1ee7a n\xf3.\n\nCu\u1ed1i c\xf9ng t\xf4i n\xf3i cho c\xe1c b\u1ea1n bi\u1ebft: C\xe1i l\u1ee3i \xedch l\u1edbn nh\u1ea5t c\u1ee7a vi\u1ec7c tr\xec Ch\xfa L\u0103ng Nghi\xeam kh\xf4ng ph\u1ea3i l\xe0 c\u1ea7u ph\xe1t t\xe0i, c\u1ea7u b\xecnh an, m\xe0 l\xe0 \u0111\u1ec3 khai m\u1edf tr\xed tu\u1ec7, \u0111\u1ec3 minh t\xe2m ki\u1ebfn t\xednh. C\xe1c b\u1ea1n nh\xecn H\u01b0 V\xe2n L\xe3o H\xf2a Th\u01b0\u1ee3ng xem, t\u1ea1i sao ng\xe0i l\u1ea1i c\xf3 th\u1ec3 s\u1ed1ng \u0111\u1ebfn 120 tu\u1ed5i? Ch\xednh l\xe0 v\xec ng\xe0y ng\xe0y ng\xe0i \u0111\u1ec1u tr\xec Ch\xfa L\u0103ng Nghi\xeam!\n\n(Tr\xedch t\u1eeb b\xe0i khai th\u1ecb "C\xf4ng \u0111\u1ee9c c\u1ee7a Ch\xfa L\u0103ng Nghi\xeam" c\u1ee7a Tuy\xean H\xf3a Th\u01b0\u1ee3ng Nh\xe2n, V\u1ea1n Ph\u1eadt Th\xe1nh Th\xe0nh)'],q,q)],t.m0),new A.atf(this),p),p.i("y.E"))
